from numbers import Real


def seconds_to_human_readable(seconds: Real) -> str:
    """把秒数转换为人类可读的时长文本，负数按 0 处理，0 秒返回 0s。"""
    remaining = max(0.0, float(seconds))
    if remaining == 0:
        return '0s'
    units = (('小时', 3600), ('分钟', 60), ('秒', 1))
    parts = []
    for label, size in units:
        count = int(remaining // size)
        if count:
            parts.append(f'{count}{label}')
            remaining -= count * size
    if not parts:
        return f'{remaining:g}s'
    return ''.join(parts)
```

