from zoneinfo import ZoneInfo, ZoneInfoNotFoundError


def format_timestamp(
    timestamp: Real,
    timezone: str | datetime.tzinfo | None = None,
    format: str = '%Y-%m-%d %H:%M:%S',
) -> str:
    """格式化时间戳；timezone 可传 datetime.timezone 或 IANA 名称字符串（pytz 名称同样适用），非法时间戳返回空字符串。"""
    if isinstance(timestamp, bool) or not isinstance(timestamp, Real):
        return ''
    if timestamp != timestamp:
        return ''
    zone: datetime.tzinfo
    if timezone is None:
        zone = datetime.timezone.utc
    elif isinstance(timezone, str):
        try:
            zone = ZoneInfo(timezone)
        except ZoneInfoNotFoundError:
            return ''
    else:
        zone = timezone
    try:
        moment = datetime.datetime.fromtimestamp(float(timestamp), tz=zone)
    except (OverflowError, OSError, ValueError):
        return ''
    return moment.strftime(format)
