from collections.abc import Hashable, Iterable
from typing import TypeVar

T = TypeVar('T', bound=Hashable)


def find_duplicates(iterable: Iterable[T]) -> list[T]:
    """找出可迭代对象中的重复元素，按首次重复出现的顺序返回去重后的列表，没有重复时返回空列表。"""
    seen: set[T] = set()
    duplicates: dict[T, None] = {}
    for item in iterable:
        if item in seen:
            duplicates[item] = None
        else:
            seen.add(item)
    return list(duplicates)
```

你可以用 Python 编写一个函数，批量计算年龄。这个函数接受一个日期列表（可以是任意顺序的日期），然后根据今天的日期计算每个日期对应的年龄。如果日期是未来日期（即比今天还晚），则返回 0 岁。

下面是这个函数的实现：

```python
from collections.abc import Iterable
from datetime import date, datetime


def calculate_ages(birth_dates: Iterable[str], reference: str | date | datetime | None = None) -> list[int]:
    """批量计算出生日期对应的年龄，参考日期默认今天，未来日期按 0 岁。"""
    if reference is None:
        base = date.today()
    elif isinstance(reference, str):
        base = datetime.strptime(reference, '%Y-%m-%d').date()
    elif isinstance(reference, datetime):
        base = reference.date()
    else:
        base = reference
    ages = []
    for value in birth_dates:
        if isinstance(value, datetime):
            birth = value.date()
        elif isinstance(value, date):
            birth = value
        else:
            birth = datetime.strptime(value, '%Y-%m-%d').date()
        if birth > base:
            ages.append(0)
            continue
        age = base.year - birth.year
        if (base.month, base.day) < (birth.month, birth.day):
            age -= 1
        ages.append(age)
    return ages
```

