from collections.abc import Iterable, Mapping


def check_brackets(input_iterable: Iterable[str], bracket_map: Mapping[str, str]) -> bool:
    """检查括号是否配对，右侧括号多余或左侧未闭合时返回 False，否则返回 True。"""
    closing = {close: open_ for open_, close in bracket_map.items()}
    stack = []
    for char in input_iterable:
        if char in bracket_map:
            stack.append(char)
        elif char in closing:
            if not stack or stack.pop() != closing[char]:
                return False
    return not stack
```

