这个实现只使用标准库，不使用任何第三方库，也不涉及头文件，全部内容都在一个 `.cpp` 文件中。

```cpp
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <unordered_map>
#include <vector>

class KNNClassifier {
public:
    KNNClassifier() = default;

    explicit KNNClassifier(int k) : k_(k) {
        if (k_ <= 0) throw std::invalid_argument("k must be positive");
    }

    void set_k(int k) {
        if (k <= 0) throw std::invalid_argument("k must be positive");
        k_ = k;
    }

    int get_k() const { return k_; }

    KNNClassifier& fit(const std::vector<std::vector<double>>& features,
                       const std::vector<int>& labels) {
        if (features.empty() || features.size() != labels.size()) {
            throw std::invalid_argument("features and labels must be non-empty and aligned");
        }
        const std::size_t dim = features.front().size();
        if (dim == 0) throw std::invalid_argument("feature dimension must be positive");
        for (const auto& row : features) {
            if (row.size() != dim) throw std::invalid_argument("rows must share one dimension");
        }
        features_ = features;
        labels_ = labels;
        fitted_ = true;
        return *this;
    }

    std::vector<int> predict(const std::vector<std::vector<double>>& samples) const {
        if (!fitted_) throw std::logic_error("predict called before fit");
        if (samples.empty()) throw std::invalid_argument("samples must not be empty");
        std::vector<int> predictions;
        predictions.reserve(samples.size());
        for (const auto& sample : samples) predictions.push_back(predict_one(sample));
        return predictions;
    }

private:
    int k_ = 3;
    bool fitted_ = false;
    std::vector<std::vector<double>> features_;
    std::vector<int> labels_;

    static double distance(const std::vector<double>& a, const std::vector<double>& b) {
        double sum = 0.0;
        for (std::size_t i = 0; i < a.size(); ++i) sum += (a[i] - b[i]) * (a[i] - b[i]);
        return std::sqrt(sum);
    }

    int predict_one(const std::vector<double>& sample) const {
        if (sample.size() != features_.front().size()) {
            throw std::invalid_argument("sample dimension mismatches training data");
        }
        std::vector<std::pair<double, int>> neighbors;
        neighbors.reserve(features_.size());
        for (std::size_t i = 0; i < features_.size(); ++i) {
            neighbors.emplace_back(distance(sample, features_[i]), labels_[i]);
        }
        const std::size_t k = std::min(static_cast<std::size_t>(k_), neighbors.size());
        std::partial_sort(neighbors.begin(),
                          neighbors.begin() + static_cast<std::ptrdiff_t>(k), neighbors.end());
        std::unordered_map<int, int> votes;
        for (std::size_t i = 0; i < k; ++i) ++votes[neighbors[i].second];
        int best_label = neighbors.front().second;
        int best_votes = -1;
        for (const auto& [label, count] : votes) {
            if (count > best_votes || (count == best_votes && label < best_label)) {
                best_votes = count;
                best_label = label;
            }
        }
        return best_label;
    }
};

int main() {
    const std::vector<std::vector<double>> features = {
        {1.0, 2.0}, {1.5, 1.8}, {5.0, 8.0}, {8.0, 8.0}, {1.0, 0.5}, {3.0, 4.5},
    };
    const std::vector<int> labels = {0, 0, 1, 1, 0, 1};
    const std::vector<std::vector<double>> samples = {{1.0, 2.0}, {8.0, 8.0}, {3.0, 4.5}};
    KNNClassifier classifier(3);
    classifier.fit(features, labels);
    const std::vector<int> predictions = classifier.predict(samples);
    for (std::size_t i = 0; i < predictions.size(); ++i) {
        std::cout << "sample " << i << " -> " << predictions[i] << std::endl;
    }
    return 0;
}
```

以下是一个使用 C++20 编写的 `KMeans` 聚类类的实现，支持 `max_iter`、`tol`、`random_state` 参数，处理空簇时随机重选中心，并提供 `predict` 方法返回聚类编号。全部代码放在一个 `.cpp` 文件中，仅使用标准库。

```cpp
#include <algorithm>
#include <cmath>
#include <iostream>
#include <numeric>
#include <random>
#include <stdexcept>
#include <vector>

class KMeans {
public:
    KMeans() = default;

    KMeans(int max_iter, double tol, int random_state)
        : max_iter_(max_iter), tol_(tol), random_state_(random_state) {
        if (max_iter_ <= 0 || tol_ <= 0.0) {
            throw std::invalid_argument("max_iter and tol must be positive");
        }
    }

    void fit(const std::vector<std::vector<double>>& data, int n_clusters) {
        if (data.empty() || n_clusters <= 0 ||
            static_cast<std::size_t>(n_clusters) > data.size()) {
            throw std::invalid_argument("data must be non-empty and n_clusters must fit it");
        }
        data_ = data;
        dim_ = data_.front().size();
        for (const auto& point : data_) {
            if (dim_ == 0 || point.size() != dim_) {
                throw std::invalid_argument("points must share one positive dimension");
            }
        }

        std::mt19937 gen(static_cast<unsigned int>(random_state_));
        std::vector<std::size_t> order(data_.size());
        std::iota(order.begin(), order.end(), 0);
        std::shuffle(order.begin(), order.end(), gen);
        centroids_.clear();
        for (int c = 0; c < n_clusters; ++c) centroids_.push_back(data_[order[c]]);

        for (int iter = 0; iter < max_iter_; ++iter) {
            if (step(gen) < tol_) break;
        }
        labels_ = assign(data_);
        fitted_ = true;
    }

    std::vector<int> predict(const std::vector<std::vector<double>>& points) const {
        if (!fitted_) throw std::logic_error("predict called before fit");
        if (points.empty()) throw std::invalid_argument("points must not be empty");
        return assign(points);
    }

private:
    int max_iter_ = 300;
    double tol_ = 1e-4;
    int random_state_ = 42;
    bool fitted_ = false;
    std::size_t dim_ = 0;
    std::vector<std::vector<double>> data_;
    std::vector<std::vector<double>> centroids_;
    std::vector<int> labels_;

    static double squared_distance(const std::vector<double>& a, const std::vector<double>& b) {
        double sum = 0.0;
        for (std::size_t i = 0; i < a.size(); ++i) sum += (a[i] - b[i]) * (a[i] - b[i]);
        return sum;
    }

    std::size_t nearest(const std::vector<double>& point) const {
        std::size_t best = 0;
        double best_distance = squared_distance(point, centroids_.front());
        for (std::size_t c = 1; c < centroids_.size(); ++c) {
            const double d = squared_distance(point, centroids_[c]);
            if (d < best_distance) { best_distance = d; best = c; }
        }
        return best;
    }

    std::vector<int> assign(const std::vector<std::vector<double>>& points) const {
        std::vector<int> labels;
        labels.reserve(points.size());
        for (const auto& point : points) labels.push_back(static_cast<int>(nearest(point)));
        return labels;
    }

    double step(std::mt19937& gen) {
        std::vector<std::vector<double>> sums(centroids_.size(), std::vector<double>(dim_, 0.0));
        std::vector<std::size_t> counts(centroids_.size(), 0);
        for (const auto& point : data_) {
            const std::size_t best = nearest(point);
            ++counts[best];
            for (std::size_t j = 0; j < dim_; ++j) sums[best][j] += point[j];
        }
        std::uniform_int_distribution<std::size_t> pick(0, data_.size() - 1);
        double shift = 0.0;
        for (std::size_t c = 0; c < sums.size(); ++c) {
            if (counts[c] == 0) {
                sums[c] = data_[pick(gen)];
            } else {
                for (std::size_t j = 0; j < dim_; ++j) sums[c][j] /= static_cast<double>(counts[c]);
            }
            shift += std::sqrt(squared_distance(centroids_[c], sums[c]));
        }
        centroids_ = sums;
        return shift;
    }
};

int main() {
    const std::vector<std::vector<double>> data = {
        {1.0, 1.0}, {1.5, 2.0}, {8.0, 8.0}, {8.5, 7.6},
    };
    KMeans kmeans(100, 1e-4, 42);
    kmeans.fit(data, 2);
    const std::vector<int> labels = kmeans.predict(data);
    for (std::size_t i = 0; i < labels.size(); ++i) {
        std::cout << i << " -> cluster " << labels[i] << std::endl;
    }
    return 0;
}
```

