class FuzzyCMeans {
public:
    explicit FuzzyCMeans(int n_clusters, double m = 2.0, int max_iter = 100,
                double tol = 1e-4, int random_state = 42)
        : n_clusters_(n_clusters), m_(m), max_iter_(max_iter),
          tol_(tol), random_state_(random_state) {
        if (n_clusters_ <= 0 || m_ <= 1.0) {
            throw std::invalid_argument("n_clusters must be positive and m above 1");
        }
        if (max_iter_ <= 0 || tol_ <= 0.0) throw std::invalid_argument("max_iter and tol must be positive");
    }

    FuzzyCMeans& fit(const std::vector<std::vector<double>>& data) {
        if (data.empty()) throw std::invalid_argument("data must not be empty");
        if (static_cast<std::size_t>(n_clusters_) > data.size()) throw std::invalid_argument("n_clusters exceeds sample count");
        data_ = data;
        const std::size_t dim = data_.front().size();
        for (const auto& row : data_) {
            if (dim == 0 || row.size() != dim) throw std::invalid_argument("samples must share one positive dimension");
        }

        std::mt19937 gen(static_cast<unsigned int>(random_state_));
        std::vector<std::size_t> order(data_.size());
        std::iota(order.begin(), order.end(), 0);
        std::shuffle(order.begin(), order.end(), gen);
        centers_.clear();
        for (int c = 0; c < n_clusters_; ++c) centers_.push_back(data_[order[c]]);
        membership_.assign(data_.size(), std::vector<double>(centers_.size(), 0.0));
        update_membership();
        for (int iter = 0; iter < max_iter_; ++iter) {
            update_centers();
            if (update_membership() < tol_) break;
        }
        generate_labels();
        return *this;
    }

    std::vector<std::vector<double>> get_membership() const { return membership_; }
    std::vector<int> get_labels() const { return labels_; }

private:
    int n_clusters_;
    double m_;
    int max_iter_;
    double tol_;
    int random_state_;
    std::vector<std::vector<double>> data_;
    std::vector<std::vector<double>> centers_;
    std::vector<std::vector<double>> membership_;
    std::vector<int> labels_;

    static double euclidean(const std::vector<double>& a, const std::vector<double>& b) {
        double sum = 0.0;
        for (std::size_t i = 0; i < a.size(); ++i) sum += (a[i] - b[i]) * (a[i] - b[i]);
        return std::sqrt(sum);
    }

    void update_centers() {
        for (std::size_t c = 0; c < centers_.size(); ++c) {
            std::vector<double> weighted(centers_[c].size(), 0.0);
            double weight_sum = 0.0;
            for (std::size_t i = 0; i < data_.size(); ++i) {
                const double w = std::pow(membership_[i][c], m_);
                weight_sum += w;
                for (std::size_t j = 0; j < weighted.size(); ++j) weighted[j] += w * data_[i][j];
            }
            if (weight_sum <= 0.0) continue;
            for (std::size_t j = 0; j < weighted.size(); ++j) centers_[c][j] = weighted[j] / weight_sum;
        }
    }

    double update_membership() {
        const double power = 2.0 / (m_ - 1.0);
        double change = 0.0;
        for (std::size_t i = 0; i < data_.size(); ++i) {
            std::vector<double> d(centers_.size());
            for (std::size_t c = 0; c < centers_.size(); ++c) {
                d[c] = euclidean(data_[i], centers_[c]) + 1e-12;
            }
            for (std::size_t c = 0; c < d.size(); ++c) {
                const double previous = membership_[i][c];
                double total = 0.0;
                for (double other : d) total += std::pow(d[c] / other, power);
                membership_[i][c] = 1.0 / total;
                change = std::max(change, std::abs(membership_[i][c] - previous));
            }
        }
        return change;
    }

    void generate_labels() {
        labels_.clear();
        for (const auto& row : membership_) {
            labels_.push_back(static_cast<int>(std::max_element(row.begin(), row.end()) - row.begin()));
        }
    }
};

int main() {
    const std::vector<std::vector<double>> data = {
        {1.0, 2.0}, {2.0, 3.0}, {2.5, 3.5},
    };
    FuzzyCMeans fcm(2);
    fcm.fit(data);
    for (int label : fcm.get_labels()) std::cout << label << ' ';
    std::cout << std::endl;
    return 0;
}
