#include <algorithm>
#include <iostream>
#include <string>

std::size_t code_point_length(unsigned char lead) {
    if (lead < 0x80) return 1;
    if ((lead >> 5) == 0x06) return 2;
    if ((lead >> 4) == 0x0E) return 3;
    if ((lead >> 3) == 0x1E) return 4;
    return 1;
}

unsigned int decode_code_point(const std::string& text, std::size_t pos, std::size_t length) {
    if (length == 1) return static_cast<unsigned char>(text[pos]);
    unsigned int code_point =
        static_cast<unsigned char>(text[pos]) & (0xFFu >> static_cast<unsigned int>(length + 1));
    for (std::size_t i = 1; i < length; ++i) {
        code_point = (code_point << 6) | (static_cast<unsigned char>(text[pos + i]) & 0x3Fu);
    }
    return code_point;
}

bool is_full_width(unsigned int code_point) {
    return (code_point >= 0x1100 && code_point <= 0x115F) ||
           (code_point >= 0x2E80 && code_point <= 0xA4CF) ||
           (code_point >= 0xAC00 && code_point <= 0xD7A3) ||
           (code_point >= 0xF900 && code_point <= 0xFAFF) ||
           (code_point >= 0xFE30 && code_point <= 0xFE4F) ||
           (code_point >= 0xFF00 && code_point <= 0xFF60) ||
           (code_point >= 0xFFE0 && code_point <= 0xFFE6) ||
           (code_point >= 0x20000 && code_point <= 0x3FFFD);
}

std::string truncate_string(const std::string& text, int width) {
    if (width <= 0) return "";
    std::string result;
    int used = 0;
    std::size_t pos = 0;
    while (pos < text.size()) {
        const std::size_t remaining = text.size() - pos;
        const std::size_t length =
            std::min(code_point_length(static_cast<unsigned char>(text[pos])), remaining);
        const int columns = is_full_width(decode_code_point(text, pos, length)) ? 2 : 1;
        if (used + columns > width) break;
        result.append(text, pos, length);
        used += columns;
        pos += length;
    }
    return result;
}

int main() {
    const std::string text = "Hello, \xE4\xBD\xA0\xE5\xA5\xBD\xEF\xBC\x81";
    std::cout << truncate_string(text, 8) << std::endl;
    std::cout << truncate_string(text, 0).size() << std::endl;
    std::cout << truncate_string(text, 12) << std::endl;
    return 0;
}
