#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>

bool atomic_write(const std::filesystem::path& file_path, const std::string& content) {
    const std::filesystem::path directory = file_path.parent_path();
    if (directory.empty() || !std::filesystem::is_directory(directory)) {
        return false;
    }
    const std::filesystem::path temp_file =
        directory / (file_path.filename().string() + ".tmp");
    {
        std::ofstream stream(temp_file, std::ios::binary | std::ios::trunc);
        if (!stream) return false;
        stream.write(content.data(), static_cast<std::streamsize>(content.size()));
        stream.flush();
        if (!stream) {
            stream.close();
            std::error_code ignored;
            std::filesystem::remove(temp_file, ignored);
            return false;
        }
    }
    std::error_code error;
    std::filesystem::rename(temp_file, file_path, error);
    if (error) {
        std::error_code ignored;
        std::filesystem::remove(temp_file, ignored);
        return false;
    }
    return true;
}

int main() {
    const std::filesystem::path target = "atomic_demo.txt";
    if (!atomic_write(target, "hello utf-8")) {
        std::cerr << "write failed" << std::endl;
        return 1;
    }
    std::cout << "written bytes: " << std::filesystem::file_size(target) << std::endl;
    std::error_code ignored;
    std::filesystem::remove(target, ignored);
    return 0;
}
