#include <cctype>
#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_value_t<Range>, char>
std::string make_url_slug(const Range& text) {
    std::string result;
    bool pending_separator = false;
    for (const auto& item : text) {
        const unsigned char code = static_cast<unsigned char>(static_cast<char>(item));
        if (std::isalnum(code) != 0) {
            if (pending_separator && !result.empty()) {
                result.push_back('-');
            }
            result.push_back(static_cast<char>(std::tolower(code)));
            pending_separator = false;
        } else {
            pending_separator = true;
        }
    }
    return result;
}

int main() {
    const std::string first = "Hello! World@123";
    const std::string_view second = "  Special--Characters  ";
    std::cout << make_url_slug(first) << std::endl;
    std::cout << make_url_slug(second) << std::endl;
    std::cout << make_url_slug(std::string{}).size() << std::endl;
    return 0;
}
