#include <algorithm>
#include <cctype>
#include <filesystem>
#include <iostream>
#include <string>
#include <vector>

std::string to_lower(std::string text) {
    std::transform(text.begin(), text.end(), text.begin(),
                   [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
    return text;
}

std::vector<std::filesystem::path> find_files_by_suffix(
    const std::filesystem::path& root, const std::vector<std::string>& suffixes) {
    std::vector<std::filesystem::path> results;
    if (!std::filesystem::exists(root) || !std::filesystem::is_directory(root)) {
        return results;
    }
    std::vector<std::string> lowered;
    lowered.reserve(suffixes.size());
    for (const auto& suffix : suffixes) {
        lowered.push_back(to_lower(suffix));
    }
    for (const auto& entry : std::filesystem::recursive_directory_iterator(root)) {
        if (!entry.is_regular_file()) continue;
        const std::string name = to_lower(entry.path().filename().string());
        for (const auto& suffix : lowered) {
            if (name.size() >= suffix.size() &&
                name.compare(name.size() - suffix.size(), suffix.size(), suffix) == 0) {
                results.push_back(entry.path());
                break;
            }
        }
    }
    std::sort(results.begin(), results.end());
    return results;
}

int main() {
    const std::vector<std::string> suffixes = {".md", ".TXT"};
    const std::vector<std::filesystem::path> files = find_files_by_suffix(".", suffixes);
    std::cout << "found " << files.size() << " files" << std::endl;
    const std::vector<std::filesystem::path> missing = find_files_by_suffix("no_such_dir", suffixes);
    std::cout << "missing: " << missing.size() << std::endl;
    return 0;
}
