### ✅ C++20 驼峰转蛇形转换器（.cpp 文件）

```cpp
#include <cctype>
#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <vector>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_value_t<Range>, char>
std::vector<std::string> convertCamelToSnake(const Range& identifier) {
    std::vector<char> chars;
    for (const auto& item : identifier) {
        chars.push_back(static_cast<char>(item));
    }
    std::vector<std::string> words;
    std::string current;
    for (std::size_t i = 0; i < chars.size(); ++i) {
        const unsigned char code = static_cast<unsigned char>(chars[i]);
        const bool upper = std::isupper(code) != 0;
        const bool plain = std::islower(code) != 0 || std::isdigit(code) != 0;
        if (!upper && !plain) {
            if (!current.empty()) words.push_back(current);
            current.clear();
            continue;
        }
        if (!upper) {
            current.push_back(static_cast<char>(std::tolower(code)));
            continue;
        }
        const bool after_lower = i > 0 &&
            (std::islower(static_cast<unsigned char>(chars[i - 1])) != 0 ||
             std::isdigit(static_cast<unsigned char>(chars[i - 1])) != 0);
        const bool before_lower =
            i + 1 < chars.size() && std::islower(static_cast<unsigned char>(chars[i + 1])) != 0;
        if (!current.empty() && (after_lower || before_lower)) {
            words.push_back(current);
            current.clear();
        }
        current.push_back(static_cast<char>(std::tolower(code)));
    }
    if (!current.empty()) words.push_back(current);
    return words;
}

std::string join_words(const std::vector<std::string>& words) {
    std::string text;
    for (const std::string& word : words) {
        if (!text.empty()) text.push_back('_');
        text += word;
    }
    return text;
}

int main() {
