    const std::string acronym = "HTTPRequest";
    std::cout << "camel_case: " << join_words(convertCamelToSnake(camel)) << std::endl;
    std::cout << "http_request: " << join_words(convertCamelToSnake(acronym)) << std::endl;
    std::cout << "empty: " << convertCamelToSnake(std::string{}).size() << std::endl;
    return 0;
}
