#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <unordered_map>

std::string trim(std::string text) {
    const std::string whitespace = " \t\n\r\f\v";
    const std::size_t first = text.find_first_not_of(whitespace);
    if (first == std::string::npos) return "";
    const std::size_t last = text.find_last_not_of(whitespace);
    return text.substr(first, last - first + 1);
}

std::unordered_map<std::string, std::string> read_config(
    const std::filesystem::path& path) {
    std::unordered_map<std::string, std::string> config;
    std::ifstream file(path);
    if (!file.is_open()) return config;
    std::string line;
    while (std::getline(file, line)) {
        const std::string trimmed = trim(line);
        if (trimmed.empty() || trimmed.front() == '#') continue;
        const std::size_t equals = trimmed.find('=');
        if (equals == std::string::npos) return {};
        const std::string key = trim(trimmed.substr(0, equals));
        const std::string value = trim(trimmed.substr(equals + 1));
        if (key.empty()) return {};
        config[key] = value;
    }
    return config;
}

int main() {
    const std::filesystem::path config_path = "config_reader.txt";
    {
        std::ofstream stream(config_path);
        stream << "host = 127.0.0.1\n";
        stream << "# comment line\n";
        stream << "\n";
        stream << "port = 8080\n";
    }
    const std::unordered_map<std::string, std::string> config = read_config(config_path);
    for (const auto& [key, value] : config) {
        std::cout << key << " = " << value << std::endl;
    }
    std::cout << "entries: " << config.size() << std::endl;
    std::cout << "missing: " << read_config("no_such_config.txt").size() << std::endl;
    std::error_code ignored;
    std::filesystem::remove(config_path, ignored);
    return 0;
}
