#include <algorithm>
#include <concepts>
#include <iostream>
#include <ranges>
#include <vector>

template <typename T>
concept Scored = requires(const T& item) {
    { item.score } -> std::convertible_to<double>;
};

template <std::ranges::input_range Range>
    requires Scored<std::ranges::range_value_t<Range>>
std::vector<std::ranges::range_value_t<Range>> sort_by_score(const Range& items) {
    using value_type = std::ranges::range_value_t<Range>;
    std::vector<value_type> result(items.begin(), items.end());
    std::ranges::sort(result, [](const value_type& left, const value_type& right) {
        return left.score < right.score;
    });
    return result;
}

