    const char* name;
};

int main() {
    const std::vector<Task> tasks = {{5, "write"}, {2, "plan"}, {8, "review"}};
    for (const Task& task : sort_by_score(tasks)) {
        std::cout << task.name << ':' << task.score << ' ';
    }
    std::cout << std::endl;

    std::cout << "original first score: " << tasks.front().score << std::endl;
    return 0;
}
