#include <algorithm>
#include <concepts>
#include <functional>
#include <iostream>
#include <iterator>
#include <vector>

template <std::input_iterator Iterator>
    requires std::convertible_to<std::iter_value_t<Iterator>, double>
std::vector<double> top_k(Iterator first, Iterator last, int k) {
    if (k <= 0) return {};
    std::vector<double> values;
    for (; first != last; ++first) {
        values.push_back(static_cast<double>(*first));
    }
    if (values.empty()) return {};
    const std::size_t limit =
        std::min(static_cast<std::size_t>(k), values.size());
    std::nth_element(values.begin(),
                     values.begin() + static_cast<std::ptrdiff_t>(limit - 1),
                     values.end(), std::greater<double>());
    values.resize(limit);
    std::sort(values.begin(), values.end(), std::greater<double>());
    return values;
}

int main() {
    const double data[] = {3.5, 1.2, 4.7, 2.8, 5.1, 0.9, 6.3, 3.1};
    for (double value : top_k(std::begin(data), std::end(data), 3)) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;

    const std::vector<int> extra = {10, 20, 30};
    std::cout << top_k(extra.begin(), extra.end(), 0).size() << std::endl;
    std::cout << top_k(extra.begin(), extra.end(), 5).size() << std::endl;
    return 0;
}
