#include <cctype>
#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <vector>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_value_t<Range>, char>
std::vector<std::string> split_words(const Range& text) {
    std::vector<char> chars;
    for (const auto& item : text) {
        chars.push_back(static_cast<char>(item));
    }
    std::vector<std::string> words;
    std::string current;
    for (std::size_t i = 0; i < chars.size(); ++i) {
        const char ch = chars[i];
        if (ch == '_' || ch == ' ') {
            if (!current.empty()) words.push_back(current);
            current.clear();
            continue;
        }
        const bool upper = std::isupper(static_cast<unsigned char>(ch)) != 0;
        const bool next_lower =
            i + 1 < chars.size() && std::islower(static_cast<unsigned char>(chars[i + 1])) != 0;
        if (upper && next_lower && !current.empty()) {
            words.push_back(current);
            current.clear();
        }
        current.push_back(ch);
    }
    if (!current.empty()) words.push_back(current);
    return words;
}

int main() {
    const std::string identifier = "Hello_World camelCase HTTPRequest";
    for (const std::string& word : split_words(identifier)) {
