        if (!stream) throw std::runtime_error("cannot open record file");
        stream << key << '=' << escape_value(value) << '\n';
    }
    std::ifstream input(file_path);
    if (!input) throw std::runtime_error("cannot read record file");
    int lines = 0;
    std::string line;
    while (std::getline(input, line)) {
