#include <iostream>
#include <string>

std::string format_number(long long value, char separator) {
    const bool negative = value < 0;
    const unsigned long long magnitude =
        negative ? 0ULL - static_cast<unsigned long long>(value)
                 : static_cast<unsigned long long>(value);
    const std::string digits = std::to_string(magnitude);
    std::string result;
    for (std::size_t i = 0; i < digits.size(); ++i) {
        if (i > 0 && (digits.size() - i) % 3 == 0) result.push_back(separator);
        result.push_back(digits[i]);
    }
    return negative ? "-" + result : result;
}

std::string format_number_with_thousands(long long value) {
    return format_number(value, ',');
}

int main() {
    const long long samples[] = {0, 999, 1000, -1000, 123456789, -1234567890123456789LL};
    for (long long sample : samples) {
        std::cout << format_number_with_thousands(sample) << std::endl;
    }
    return 0;
}
