### ✅ C++20 滑动窗口函数（单文件实现）

```cpp
#include <concepts>
#include <iostream>
#include <iterator>
#include <vector>

template <std::forward_iterator Iterator>
    requires std::copyable<std::iter_value_t<Iterator>>
std::vector<std::vector<std::iter_value_t<Iterator>>> sliding_window(
    Iterator first, Iterator last, std::size_t window_size) {
    using value_type = std::iter_value_t<Iterator>;
    const std::vector<value_type> data(first, last);
    std::vector<std::vector<value_type>> windows;
    if (window_size == 0 || window_size > data.size()) {
        return windows;
    }
    windows.reserve(data.size() - window_size + 1);
    for (std::size_t start = 0; start + window_size <= data.size(); ++start) {
        windows.emplace_back(data.begin() + static_cast<std::ptrdiff_t>(start),
                             data.begin() + static_cast<std::ptrdiff_t>(start + window_size));
    }
    return windows;
}

int main() {
    const std::vector<int> data = {1, 2, 3, 4, 5, 6, 7};
    for (const auto& window : sliding_window(data.begin(), data.end(), 3)) {
        for (int value : window) std::cout << value << ' ';
        std::cout << std::endl;
    }
    std::cout << sliding_window(data.begin(), data.end(), 20).size() << std::endl;
    return 0;
}
