std::string sanitize_filename(const std::string& filename, int max_length = 255) {
    if (max_length <= 0) {
        throw std::invalid_argument("max_length must be positive");
    }
    const std::size_t limit = static_cast<std::size_t>(max_length);
    std::string result;
    bool has_valid = false;
    for (char ch : filename) {
        const unsigned char code = static_cast<unsigned char>(ch);
        const bool valid = std::isalnum(code) != 0 || ch == '_' || ch == '-' || ch == '.';
        if (valid) has_valid = true;
        if (result.size() < limit) result.push_back(valid ? ch : '_');
    }
    if (!has_valid) return "untitled";
    return result;
}

