#include <filesystem>
#include <iostream>
#include <stdexcept>

std::filesystem::path ensure_directory_exists(const std::filesystem::path& path) {
    if (path.empty()) {
        throw std::invalid_argument("path must not be empty");
    }
    std::error_code error;
    const std::filesystem::path absolute = std::filesystem::weakly_canonical(path, error);
    if (error) {
        throw std::filesystem::filesystem_error("cannot resolve path", path, error);
    }
    if (!std::filesystem::exists(absolute)) {
        std::filesystem::create_directories(absolute, error);
        if (error) {
            throw std::filesystem::filesystem_error("cannot create directory", absolute, error);
        }
    }
    return absolute;
}

int main() {
    const std::filesystem::path target = "demo_dir/nested/subdir";
    const std::filesystem::path absolute = ensure_directory_exists(target);
    std::cout << "resolved: " << absolute << std::endl;
    std::cout << "is directory: " << std::filesystem::is_directory(absolute) << std::endl;
    const std::filesystem::path again = ensure_directory_exists(target);
    std::cout << "idempotent: " << (again == absolute) << std::endl;
    std::error_code ignored;
    std::filesystem::remove_all("demo_dir", ignored);
    return 0;
}
