#include <concepts>
#include <functional>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

template <typename T>
concept Hashable = requires(const T& value) {
    { std::hash<T>{}(value) } -> std::convertible_to<std::size_t>;
};

template <typename K, typename V>
    requires Hashable<K> && Hashable<V> && std::copyable<K> && std::copyable<V>
std::unordered_map<V, std::vector<K>> reverseMap(const std::unordered_map<K, V>& original) {
    std::unordered_map<V, std::vector<K>> reversed;
    reversed.reserve(original.size());
    for (const auto& [key, value] : original) {
        reversed[value].push_back(key);
    }
    return reversed;
}

int main() {
    const std::unordered_map<std::string, int> original = {
        {"a", 1},
        {"b", 2},
        {"c", 1},
        {"d", 3},
    };
    const std::unordered_map<int, std::vector<std::string>> reversed = reverseMap(original);
    for (const auto& [value, keys] : reversed) {
        std::cout << value << ':';
        for (const std::string& key : keys) std::cout << ' ' << key;
        std::cout << std::endl;
    }
    return 0;
}
