#include <cctype>
#include <concepts>
#include <iostream>
#include <string>
#include <unordered_map>

template <typename Map>
concept StringLookup = requires(const Map& values, const std::string& key) {
    { values.find(key) } -> std::convertible_to<typename Map::const_iterator>;
    { values.find(key)->second } -> std::convertible_to<std::string>;
};

template <typename Map>
    requires StringLookup<Map>
std::string fill_template(const std::string& text, const Map& values) {
    std::string result;
    std::size_t pos = 0;
    while (pos < text.size()) {
        if (text[pos] != '$') {
            result.push_back(text[pos]);
            ++pos;
            continue;
        }
        std::size_t end = pos + 1;
        while (end < text.size() &&
               (std::isalnum(static_cast<unsigned char>(text[end])) != 0 || text[end] == '_')) {
            ++end;
        }
        if (end == pos + 1) {
            result.push_back('$');
            ++pos;
            continue;
        }
        const std::string name = text.substr(pos + 1, end - pos - 1);
        const auto found = values.find(name);
        if (found != values.end()) {
            result += found->second;
        } else {
            result.append(text, pos, end - pos);
        }
        pos = end;
    }
    return result;
}

int main() {
    const std::unordered_map<std::string, std::string> values = {
        {"name", "Alice"},
        {"city", "Beijing"},
    };
    const std::string message = "Hello, $name! Welcome to $city, $name.";
    std::cout << fill_template(message, values) << std::endl;
    std::cout << fill_template("$missing and $ also $", values) << std::endl;
    return 0;
}
