#include <concepts>
#include <iostream>
#include <vector>

template <typename T, typename... Rest>
    requires (std::same_as<Rest, std::vector<T>> && ...)
std::vector<T> merge_sequences(const std::vector<T>& first, const Rest&... rest) {
    const std::vector<const std::vector<T>*> sequences = {&first, &rest...};
    std::vector<std::size_t> positions(sequences.size(), 0);
    std::vector<T> merged;
    bool advanced = true;
    while (advanced) {
        advanced = false;
        for (std::size_t s = 0; s < sequences.size(); ++s) {
            if (positions[s] < sequences[s]->size()) {
                merged.push_back((*sequences[s])[positions[s]]);
                ++positions[s];
                advanced = true;
            }
        }
    }
    return merged;
}

int main() {
    const std::vector<int> first = {1, 2, 3};
    const std::vector<int> second = {4, 5};
    const std::vector<int> third = {6, 7, 8, 9};
    for (int value : merge_sequences(first, second, third)) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;

    const std::vector<int> only = {10, 11};
    std::cout << merge_sequences(only).size() << std::endl;
    return 0;
}
