#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

std::vector<std::string> fold_text(const std::string& text, int width) {
    if (width <= 0) {
        throw std::invalid_argument("width must be positive");
    }
    std::vector<std::string> lines;
    if (text.empty()) return lines;
    const std::size_t limit = static_cast<std::size_t>(width);
    std::size_t start = 0;
    while (true) {
        const std::size_t newline = text.find('\n', start);
        const std::string paragraph = newline == std::string::npos
            ? text.substr(start)
            : text.substr(start, newline - start);
        for (std::size_t offset = 0; offset < paragraph.size(); offset += limit) {
            lines.push_back(paragraph.substr(offset, limit));
        }
        if (paragraph.empty()) lines.push_back(paragraph);
        if (newline == std::string::npos) break;
        start = newline + 1;
    }
    return lines;
}

int main() {
    const std::string text = "This is an example of folded text.\nSecond paragraph stays.";
    for (const std::string& line : fold_text(text, 20)) {
        std::cout << '[' << line << ']' << std::endl;
    }
    std::cout << fold_text("", 10).size() << std::endl;
    return 0;
}
```

