#include <concepts>
#include <iostream>
#include <iterator>
#include <vector>

template <std::forward_iterator Iterator, typename KeyFunc>
    requires std::invocable<KeyFunc, std::iter_reference_t<Iterator>> &&
             std::totally_ordered<
                 std::invoke_result_t<KeyFunc, std::iter_reference_t<Iterator>>>
std::vector<std::iter_value_t<Iterator>> stable_sort_by_key(Iterator first, Iterator last,
                                                            KeyFunc key_func) {
    using value_type = std::iter_value_t<Iterator>;
    std::vector<value_type> result(first, last);
    std::ranges::stable_sort(
        result, [&key_func](const value_type& left, const value_type& right) {
            return key_func(left) < key_func(right);
        });
    return result;
}

int main() {
    const std::vector<int> data = {3, 1, 4, 1, 5, 9, 2, 6};
    for (int value : stable_sort_by_key(std::begin(data), std::end(data),
                                       [](int item) { return item % 3; })) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;

    const std::vector<int> sorted = stable_sort_by_key(data.begin(), data.end(),
                                                       [](int item) { return item; });
