#include <iostream>
#include <ranges>
#include <string>
#include <string_view>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_value_t<Range>, char>
std::string highlight_keyword(const std::string& text, const Range& keyword) {
    std::string needle;
    for (const auto& item : keyword) {
        needle.push_back(static_cast<char>(item));
    }
    if (needle.empty()) return text;
    std::string result;
    std::size_t start = 0;
    while (true) {
        const std::size_t found = text.find(needle, start);
        if (found == std::string::npos) break;
        result.append(text, start, found - start);
        result += "<mark>";
        result += needle;
        result += "</mark>";
        start = found + needle.size();
    }
    result.append(text, start, std::string::npos);
    return result;
}

int main() {
    const std::string text = "This sample text has a keyword and another keyword.";
    std::cout << highlight_keyword(text, std::string{"keyword"}) << std::endl;
    std::cout << highlight_keyword(text, std::string_view{"keyword"}) << std::endl;
    std::cout << highlight_keyword(text, std::string{}) << std::endl;
    return 0;
}
