#include <filesystem>
#include <fstream>
#include <iostream>
#include <system_error>

long long directory_size(const std::filesystem::path& root) {
    std::error_code status_error;
    if (!std::filesystem::is_directory(root, status_error) || status_error) {
        return 0;
    }
    long long total = 0;
    std::error_code iteration_error;
    for (const std::filesystem::directory_entry& entry :
         std::filesystem::directory_iterator(root, iteration_error)) {
        std::error_code entry_error;
        if (!entry.is_regular_file(entry_error) || entry_error) continue;
        total += static_cast<long long>(entry.file_size(entry_error));
    }
    return total;
}

int main() {
    const std::filesystem::path root = "demo_size";
    std::filesystem::create_directories(root);
    {
        std::ofstream first(root / "a.txt", std::ios::binary);
        first << "hello";
        std::ofstream second(root / "b.txt", std::ios::binary);
        second << "world!";
    }
    std::cout << "bytes: " << directory_size(root) << std::endl;
    std::cout << "missing: " << directory_size("no_such_dir") << std::endl;
    std::error_code ignored;
    std::filesystem::remove_all(root, ignored);
