#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <utility>

std::pair<int, int> calculate_page_bounds(int page, int page_size, int total) {
    if (page_size <= 0) {
        throw std::invalid_argument("page_size must be positive");
    }
    if (total < 0) {
        throw std::invalid_argument("total must not be negative");
    }
    if (total == 0) return {0, 0};
    const int total_pages = (total + page_size - 1) / page_size;
    int current = page < 1 ? 1 : page;
    if (current > total_pages) current = total_pages;
    const int start = (current - 1) * page_size;
    const int end = std::min(start + page_size - 1, total - 1);
    return {start, end};
}

int main() {
    const int pages[] = {1, 2, 3, 0};
    for (int page : pages) {
        const auto [start, end] = calculate_page_bounds(page, 4, 10);
        std::cout << page << " -> [" << start << ", " << end << ']' << std::endl;
    }
    const auto [first, last] = calculate_page_bounds(1, 10, 5);
    std::cout << "single page -> [" << first << ", " << last << ']' << std::endl;
    return 0;
}
