    const std::vector<value_type> right(first_right, last_right);
    const std::unordered_set<value_type> left_set(left.begin(), left.end());
    const std::unordered_set<value_type> right_set(right.begin(), right.end());
    std::vector<value_type> only_left;
    std::vector<value_type> only_right;
    std::vector<value_type> union_all;
    std::unordered_set<value_type> seen;
    for (const value_type& value : left) {
        if (right_set.find(value) == right_set.end()) only_left.push_back(value);
    }
    for (const value_type& value : right) {
        if (left_set.find(value) == left_set.end()) only_right.push_back(value);
    }
    for (const value_type& value : left) {
        if (seen.insert(value).second) union_all.push_back(value);
    }
    for (const value_type& value : right) {
        if (seen.insert(value).second) union_all.push_back(value);
    }
    return {only_left, only_right, union_all};
}

int main() {
