    std::cout << "only right: " << only_right.size() << std::endl;
    std::cout << "union: " << union_all.size() << std::endl;

    const std::vector<int> empty;
    const auto [a, b, c] = compare_sets(empty.begin(), empty.end(), empty.begin(), empty.end());
    std::cout << a.size() << b.size() << c.size() << std::endl;
