#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_reference_t<Range>, std::string_view>
std::vector<std::string> remove_prefix_suffix(const Range& items,
                                              std::string_view prefix,
                                              std::string_view suffix) {
    std::vector<std::string> result;
    result.reserve(static_cast<std::size_t>(std::ranges::distance(items)));
    for (const auto& item : items) {
        std::string_view view(item);
        if (!prefix.empty() && view.starts_with(prefix)) {
            view.remove_prefix(prefix.size());
        }
        if (!suffix.empty() && view.size() >= suffix.size() && view.ends_with(suffix)) {
            view.remove_suffix(suffix.size());
        }
        result.emplace_back(view);
    }
    return result;
}

int main() {
    const std::vector<std::string> inputs{"hello world hello", "hello", "world"};
    const std::vector<std::string> stripped =
        remove_prefix_suffix(inputs, "hello", "hello");
    for (const std::string& item : stripped) {
        std::cout << '[' << item << "]\n";
    }
    return 0;
}
