#include <cstddef>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>

class TempFile {
public:
    explicit TempFile(const std::string& suffix = "") {
        std::error_code error;
        const std::filesystem::path directory = std::filesystem::temp_directory_path(error);
        if (error) {
            throw std::invalid_argument("temporary directory is not available");
        }
        if (!suffix.empty() && suffix.front() != '.') {
            throw std::invalid_argument("suffix must start with a dot");
        }
        path_ = directory / ("tmp" + std::to_string(++counter_) + suffix);
        std::ofstream probe(path_, std::ios::binary | std::ios::trunc);
        if (!probe) {
            throw std::invalid_argument("cannot create temporary file");
        }
    }

    ~TempFile() {
        std::error_code error;
        std::filesystem::remove(path_, error);
    }

    TempFile(const TempFile&) = delete;
    TempFile& operator=(const TempFile&) = delete;

    const std::filesystem::path& path() const noexcept {
        return path_;
    }

private:
    static inline std::size_t counter_ = 0;
    std::filesystem::path path_;
};

int main() {
    TempFile temporary(".log");
    std::cout << temporary.path().generic_string() << '\n';
    std::ofstream writer(temporary.path(), std::ios::app);
    writer << "temporary payload\n";
    writer.close();
    return 0;
}
