#include <chrono>
#include <concepts>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <tuple>
#include <utility>

template <typename Result, typename Callable, typename... Args>
class retry_wrapper {
public:
    retry_wrapper(int max_tries, double interval_seconds, Callable callable, Args... args)
        : max_tries_(max_tries),
          interval_seconds_(interval_seconds),
          callable_(std::move(callable)),
          args_(std::move(args)...) {
        if (max_tries_ < 1) {
            throw std::invalid_argument("max_tries must be positive");
        }
        if (interval_seconds_ < 0.0) {
            throw std::invalid_argument("interval_seconds must not be negative");
        }
    }

    Result operator()() {
        for (int attempt = 1; attempt <= max_tries_; ++attempt) {
            try {
                return std::apply(
                    [this](auto&... unpacked) {
                        return std::invoke(callable_, unpacked...);
                    },
                    args_);
            } catch (...) {
                if (attempt == max_tries_) {
                    throw;
                }
                std::this_thread::sleep_for(std::chrono::duration<double>(interval_seconds_));
            }
        }
        throw std::logic_error("retry loop finished without a result");
    }

private:
    int max_tries_;
    double interval_seconds_;
    Callable callable_;
    std::tuple<Args...> args_;
};

template <typename Callable, typename... Args>
    requires std::invocable<Callable&, Args&...>
retry_wrapper<std::invoke_result_t<Callable&, Args&...>, Callable, Args...> retry(
    int max_tries, double interval_seconds, Callable callable, Args... args) {
    using result_type = std::invoke_result_t<Callable&, Args&...>;
    return retry_wrapper<result_type, Callable, Args...>(
        max_tries, interval_seconds, std::move(callable), std::move(args)...);
}

int main() {
    int attempts = 0;
    auto flaky = [&attempts]() -> int {
        ++attempts;
        if (attempts < 3) {
            throw std::runtime_error("temporary failure");
        }
        return attempts;
    };
    auto wrapped = retry(5, 0.01, flaky);
    std::cout << wrapped() << '\n';
    return 0;
}
```

