#include <iostream>
#include <iterator>
#include <utility>
#include <vector>

template <std::forward_iterator Iterator, typename Predicate>
    requires std::predicate<Predicate&, std::iter_value_t<Iterator>&>
std::pair<std::vector<std::iter_value_t<Iterator>>, std::vector<std::iter_value_t<Iterator>>>
split_sequence(const std::pair<Iterator, Iterator>& range, Predicate predicate) {
    std::vector<std::iter_value_t<Iterator>> matched;
    std::vector<std::iter_value_t<Iterator>> rest;
    for (Iterator current = range.first; current != range.second; ++current) {
        if (predicate(*current)) {
            matched.push_back(*current);
        } else {
            rest.push_back(*current);
        }
    }
    return {std::move(matched), std::move(rest)};
}

