#include <iostream>
#include <string>
#include <string_view>
#include <utility>

std::string format_duration(double seconds) {
    if (seconds < 0.0) {
        seconds = 0.0;
    }
    long long total_ms = std::llround(seconds * 1000.0);
    if (total_ms <= 0) {
        return "0s";
    }
    const std::pair<long long, std::string_view> units[] = {
        {86400000LL, "d"}, {3600000LL, "h"}, {60000LL, "m"}, {1000LL, "s"}, {1LL, "ms"},
    };
    std::string result;
    for (const auto& [unit_ms, label] : units) {
        if (total_ms >= unit_ms) {
            const long long count = total_ms / unit_ms;
            total_ms %= unit_ms;
            if (!result.empty()) {
                result.push_back(' ');
            }
            result += std::to_string(count);
            result += label;
        }
    }
    return result;
}

int main() {
    const double samples[] = {0.0, 1.5, 60.0, 3600.0, 86400.0, 123456.789, -100.0};
    for (double sample : samples) {
        std::cout << sample << " -> " << format_duration(sample) << '\n';
    }
    return 0;
}
