```cpp
#include <chrono>
#include <concepts>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <utility>

template <typename Callable>
class rate_limiter {
public:
    explicit rate_limiter(Callable callable, double interval_seconds = 0.0)
        : callable_(std::move(callable)), interval_seconds_(interval_seconds) {
        if (interval_seconds_ < 0.0) {
            throw std::invalid_argument("interval_seconds must not be negative");
        }
    }

    template <typename... Args>
        requires std::invocable<Callable&, Args...>
    std::invoke_result_t<Callable&, Args...> operator()(Args&&... args) {
        if (interval_seconds_ > 0.0) {
            const auto now = std::chrono::steady_clock::now();
            if (last_call_.time_since_epoch().count() != 0) {
                const auto interval = std::chrono::duration_cast<std::chrono::steady_clock::duration>(
                    std::chrono::duration<double>(interval_seconds_));
                const auto earliest = last_call_ + interval;
                if (now < earliest) {
                    std::this_thread::sleep_for(earliest - now);
                }
            }
            last_call_ = std::chrono::steady_clock::now();
        }
        return std::invoke(callable_, std::forward<Args>(args)...);
    }

private:
    Callable callable_;
    double interval_seconds_;
    std::chrono::steady_clock::time_point last_call_{};
};

template <typename Callable>
    requires std::copy_constructible<Callable>
rate_limiter<Callable> rate_limited(Callable callable, double interval_seconds = 0.0) {
    return rate_limiter<Callable>(std::move(callable), interval_seconds);
}

int main() {
    auto printer = [](int value) { std::cout << "called " << value << '\n'; };
    auto limited = rate_limited(printer, 0.01);
    limited(1);
    limited(2);
    auto immediate = rate_limited(printer, 0.0);
    immediate(3);
    immediate(4);
    return 0;
}
```

