    using value_type = std::ranges::range_value_t<std::iter_value_t<InputIterator>>;
    std::vector<value_type> result;
    std::set<value_type> seen;
    for (InputIterator outer = first; outer != last; ++outer) {
        for (const value_type& element : *outer) {
            if (seen.insert(element).second) {
                result.push_back(element);
            }
        }
    }
    return result;
}

int main() {
    const std::vector<std::vector<int>> rows{{1, 2, 3}, {2, 3, 4}, {4, 5, 6}};
    const std::vector<int> flat = flatten_and_unique(rows.begin(), rows.end());
