```cpp
#include <chrono>
#include <concepts>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <utility>

template <typename T>
concept boolean_testable = requires(const T& value) {
    { static_cast<bool>(value) } -> std::convertible_to<bool>;
};

template <typename Callable>
class timed_callable {
public:
    explicit timed_callable(Callable callable) : callable_(std::move(callable)) {
        if constexpr (boolean_testable<Callable>) {
            if (!static_cast<bool>(callable_)) {
                throw std::invalid_argument("callable must not be empty");
            }
        }
    }

    template <typename... Args>
        requires std::invocable<Callable&, Args...>
    std::invoke_result_t<Callable&, Args...> operator()(Args&&... args) {
        const timer guard;
        return std::invoke(callable_, std::forward<Args>(args)...);
    }

private:
    struct timer {
        timer() : start_(std::chrono::steady_clock::now()) {}

        ~timer() {
            const double seconds =
                std::chrono::duration<double>(std::chrono::steady_clock::now() - start_).count();
            std::cout << "elapsed: " << seconds << " s\n";
        }

        std::chrono::steady_clock::time_point start_;
    };

    Callable callable_;
};

template <typename Callable>
    requires std::copy_constructible<Callable>
timed_callable<Callable> timed_call(Callable callable) {
    return timed_callable<Callable>(std::move(callable));
}

void example_function() {
    std::cout << "example function ran\n";
}

void example_function_that_throws() {
    throw std::runtime_error("example failure");
}

int main() {
    auto normal = timed_call(example_function);
    normal();
    auto failing = timed_call(example_function_that_throws);
    try {
        failing();
    } catch (const std::exception& error) {
        std::cout << "caught: " << error.what() << '\n';
    }
    auto printer = timed_call([](int value) { std::cout << "value " << value << '\n'; });
    printer(7);
    return 0;
}
```

