#include <algorithm>
#include <cstddef>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

template <typename Iterator>
    requires std::forward_iterator<Iterator>
std::vector<std::iter_value_t<Iterator>> shift_right(Iterator first, Iterator last, int shift) {
    std::vector<std::iter_value_t<Iterator>> values(first, last);
    const std::ptrdiff_t size = static_cast<std::ptrdiff_t>(values.size());
    if (size == 0 || shift == 0) {
        return values;
    }
    std::ptrdiff_t offset = static_cast<std::ptrdiff_t>(shift) % size;
    if (offset < 0) {
        offset += size;
    }
    if (offset == 0) {
        return values;
    }
    std::rotate(values.begin(), values.end() - offset, values.end());
    return values;
}

int main() {
    const std::vector<int> values{1, 2, 3, 4, 5};
    for (int shift : {2, 0, -2}) {
        const std::vector<int> shifted = shift_right(values.begin(), values.end(), shift);
        std::cout << shift << ":";
        for (int value : shifted) {
            std::cout << ' ' << value;
        }
        std::cout << '\n';
    }
    const std::string text = "hello";
    const std::vector<char> rotated = shift_right(text.begin(), text.end(), 2);
    for (char letter : rotated) {
        std::cout << letter;
    }
    std::cout << '\n';
    return 0;
}
