#include <chrono>
#include <iostream>
#include <stdexcept>
#include <vector>

std::vector<std::chrono::year_month_day> generate_date_range(
    const std::chrono::year_month_day& start,
    const std::chrono::year_month_day& end,
    int step = 1) {
    if (step <= 0) {
        throw std::invalid_argument("step must be positive");
    }
    std::vector<std::chrono::year_month_day> dates;
    std::chrono::sys_days current = std::chrono::sys_days(start);
    const std::chrono::sys_days last = std::chrono::sys_days(end);
    if (current > last) {
        return dates;
    }
    while (current <= last) {
        dates.push_back(std::chrono::year_month_day{current});
        current += std::chrono::days(step);
    }
    return dates;
}

int main() {
    const std::chrono::year_month_day start{std::chrono::year{2025}, std::chrono::month{3}, std::chrono::day{1}};
    const std::chrono::year_month_day end{std::chrono::year{2025}, std::chrono::month{3}, std::chrono::day{5}};
    for (const std::chrono::year_month_day& date : generate_date_range(start, end)) {
        std::cout << static_cast<int>(date.year()) << '-' << static_cast<unsigned>(date.month())
                  << '-' << static_cast<unsigned>(date.day()) << '\n';
    }
    const std::chrono::year_month_day reversed_start{std::chrono::year{2025}, std::chrono::month{3}, std::chrono::day{9}};
