```cpp
#include <any>
#include <concepts>
#include <functional>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <typeinfo>
#include <unordered_map>
#include <utility>

template <typename T>
concept streamable = requires(std::ostream& stream, const T& value) {
    stream << value;
};

template <typename Callable>
class memoizer {
public:
    explicit memoizer(Callable callable) : callable_(std::move(callable)) {}

    template <typename... Args>
        requires std::invocable<Callable&, const Args&...> && (streamable<Args> && ...)
    std::invoke_result_t<Callable&, const Args&...> operator()(const Args&... args) {
        using result_type = std::invoke_result_t<Callable&, const Args&...>;
        const std::string key = make_key(args...);
        const auto found = cache_.find(key);
        if (found != cache_.end()) {
            if (found->second.type() != typeid(result_type)) {
                throw std::logic_error("cached value type does not match the requested type");
            }
            return std::any_cast<result_type>(found->second);
        }
        result_type result = std::invoke(callable_, args...);
        cache_.emplace(key, result);
        return result;
    }

private:
    template <typename... Args>
    static std::string make_key(const Args&... args) {
        std::ostringstream stream;
        stream.precision(std::numeric_limits<long double>::max_digits10);
        ((stream << args << '\x1f'), ...);
        return stream.str();
    }

    Callable callable_;
    std::unordered_map<std::string, std::any> cache_;
};

template <typename Callable>
    requires std::copy_constructible<Callable>
memoizer<Callable> memoize(Callable callable) {
    return memoizer<Callable>(std::move(callable));
}

int main() {
    int calls = 0;
    auto square = [&calls](int value) {
        ++calls;
        return value * value;
    };
    auto cached = memoize(square);
    std::cout << cached(4) << ' ' << cached(4) << ' ' << cached(5) << '\n';
    std::cout << calls << '\n';
    return 0;
}
```

