#include <iostream>
#include <iterator>
#include <random>
#include <stdexcept>
#include <vector>

template <typename Iterator>
    requires std::forward_iterator<Iterator>
std::vector<std::iter_value_t<Iterator>> sample(Iterator first, Iterator last, int k,
                                                unsigned int seed) {
    if (k < 0) {
        throw std::invalid_argument("k must not be negative");
    }
    std::vector<std::iter_value_t<Iterator>> values(first, last);
    const std::size_t wanted = static_cast<std::size_t>(k);
    if (wanted >= values.size()) {
        return values;
    }
