#include <chrono>
#include <cmath>
#include <ctime>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>

std::string format_timestamp(double seconds, int timezone_offset_hours = 0,
                             const std::string& format = "%Y-%m-%d %H:%M:%S") {
    if (!std::isfinite(seconds)) {
        return {};
    }
    if (timezone_offset_hours < -12 || timezone_offset_hours > 14) {
        throw std::invalid_argument("timezone offset must be within [-12, 14] hours");
    }
    if (seconds < -62167219200.0 || seconds > 253402300799.0) {
        return {};
    }
    const auto point = std::chrono::system_clock::time_point(
        std::chrono::duration_cast<std::chrono::system_clock::duration>(
            std::chrono::duration<double>(seconds)));
    const std::time_t raw = std::chrono::system_clock::to_time_t(point);
    const std::time_t shifted =
        raw + static_cast<std::time_t>(timezone_offset_hours) * static_cast<std::time_t>(3600);
    const std::tm* utc = std::gmtime(&shifted);
    if (utc == nullptr) {
        return {};
    }
    std::tm value = *utc;
    std::ostringstream stream;
    stream << std::put_time(&value, format.c_str());
    return stream.str();
}

int main() {
    std::cout << format_timestamp(1696156800.0) << '\n';
    std::cout << format_timestamp(1696156800.0, 8, "%Y-%m-%d %H:%M:%S") << '\n';
    std::cout << (format_timestamp(-1.0e18).empty() ? "empty" : "filled") << '\n';
    return 0;
}
