```cpp
#include <any>
#include <concepts>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <type_traits>
#include <utility>

template <typename Callable>
class once_callable {
public:
    explicit once_callable(Callable callable) : callable_(std::move(callable)) {}

    template <typename... Args>
        requires std::invocable<Callable&, Args...>
    std::invoke_result_t<Callable&, Args...> operator()(Args&&... args) {
        using result_type = std::invoke_result_t<Callable&, Args...>;
        if (executed_) {
            return cached_value<result_type>();
        }
        if constexpr (std::is_void_v<result_type>) {
            std::invoke(callable_, std::forward<Args>(args)...);
            executed_ = true;
        } else {
            result_ = std::invoke(callable_, std::forward<Args>(args)...);
            executed_ = true;
            return std::any_cast<result_type>(result_);
        }
    }

private:
    template <typename Result>
    Result cached_value() {
        if constexpr (std::is_void_v<Result>) {
            return;
        } else {
            if (!result_.has_value()) {
                throw std::logic_error("the cached result is not available for this call signature");
            }
            return std::any_cast<Result>(result_);
        }
    }

    Callable callable_;
    bool executed_ = false;
    std::any result_;
};

template <typename Callable>
    requires std::copy_constructible<Callable>
once_callable<Callable> once(Callable callable) {
    return once_callable<Callable>(std::move(callable));
}

int add(int left, int right) {
    std::cout << "adding\n";
    return left + right;
}

int main() {
    auto once_add = once(add);
    std::cout << once_add(2, 3) << ' ' << once_add(4, 5) << '\n';
    int calls = 0;
    auto once_count = once([&calls]() { ++calls; return calls; });
    std::cout << once_count() << ' ' << once_count() << '\n';
    return 0;
}
```

