#include <stdexcept>
#include <string>

std::string mask_email(const std::string& email, int keep) {
    if (keep < 0) {
        throw std::invalid_argument("keep must not be negative");
    }
    const std::size_t at = email.find('@');
    if (at == std::string::npos) {
        return email;
    }
    const std::string username = email.substr(0, at);
    const std::size_t visible = static_cast<std::size_t>(keep);
    if (username.empty() || visible >= username.size()) {
        return email;
    }
    std::string result = username.substr(0, visible);
    result.append(username.size() - visible, '*');
    result += email.substr(at);
    return result;
}

int main() {
