#include <stdexcept>

long long align_timestamp_to_granularity(long long timestamp, int granularity) {
    if (granularity <= 0) {
        throw std::invalid_argument("granularity must be positive");
    }
    const long long step = static_cast<long long>(granularity);
    const long long remainder = timestamp % step;
    long long aligned = timestamp - remainder;
    if (remainder < 0) {
        if (aligned < std::numeric_limits<long long>::min() + step) {
            return std::numeric_limits<long long>::min();
        }
        aligned -= step;
    }
    return aligned;
}

