#include <concepts>
#include <cstddef>
#include <functional>
#include <iostream>
#include <ranges>
#include <unordered_set>
#include <vector>

template <typename T>
concept hashable = requires(const T& value) {
    { std::hash<T>()(value) } -> std::convertible_to<std::size_t>;
};

template <typename Range>
    requires std::ranges::input_range<Range> && hashable<std::ranges::range_value_t<Range>>
std::vector<std::ranges::range_value_t<Range>> findDuplicates(const Range& range) {
    using value_type = std::ranges::range_value_t<Range>;
    std::unordered_set<value_type> seen;
    std::unordered_set<value_type> reported;
    std::vector<value_type> duplicates;
    for (const auto& element : range) {
        if (!seen.insert(element).second && reported.insert(element).second) {
            duplicates.push_back(element);
        }
    }
    return duplicates;
}

int main() {
    const std::vector<int> values{1, 2, 3, 2, 4, 5, 2, 6, 7, 8, 9, 2};
    for (int value : findDuplicates(values)) {
        std::cout << value << ' ';
    }
    std::cout << '\n';
    const std::vector<int> unique{1, 2, 3};
    std::cout << findDuplicates(unique).size() << '\n';
    return 0;
}
