#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>

template <std::ranges::input_range Segments>
    requires std::convertible_to<std::ranges::range_reference_t<Segments>, std::string_view>
std::string normalize_whitespace(const Segments& segments) {
    std::string joined;
    for (const auto& segment : segments) {
        joined += std::string(std::string_view(segment));
    }
    std::string result;
    bool pending_space = false;
    for (unsigned char character : joined) {
        if (std::isspace(character) != 0) {
            pending_space = !result.empty();
        } else {
            if (pending_space) {
                result.push_back(' ');
            }
            pending_space = false;
            result.push_back(static_cast<char>(character));
        }
    }
    return result;
}

int main() {
    const std::vector<std::string> segments{"Hello   ", "   World   ", "   ", " test  "};
    std::cout << '[' << normalize_whitespace(segments) << "]\n";
    const std::vector<std::string> blank{"   ", " \t "};
    std::cout << normalize_whitespace(blank).size() << '\n';
    return 0;
}
