std::chrono::year_month_day parse_date(const std::string& text) {
    std::istringstream stream(text);
    std::tm parsed{};
    stream >> std::get_time(&parsed, "%Y-%m-%d");
    if (stream.fail() || !stream.eof()) {
        throw std::invalid_argument("date must use the YYYY-MM-DD format");
    }
    const std::chrono::year_month_day date{
        std::chrono::year{parsed.tm_year + 1900},
        std::chrono::month{static_cast<unsigned>(parsed.tm_mon + 1)},
        std::chrono::day{static_cast<unsigned>(parsed.tm_mday)}};
    if (!date.ok()) {
        throw std::invalid_argument("date is out of range");
    }
    return date;
}

std::chrono::year_month_day today() {
    const std::time_t now = std::time(nullptr);
    const std::tm* local = std::localtime(&now);
    if (local == nullptr) {
        throw std::invalid_argument("cannot read the current time");
    }
    return std::chrono::year_month_day{std::chrono::year{local->tm_year + 1900},
                                       std::chrono::month{static_cast<unsigned>(local->tm_mon + 1)},
                                       std::chrono::day{static_cast<unsigned>(local->tm_mday)}};
}

int calculate_age(const std::chrono::year_month_day& birth,
                  const std::chrono::year_month_day& reference) {
    if (birth > reference) {
        return 0;
    }
    int age = static_cast<int>(reference.year()) - static_cast<int>(birth.year());
    if (std::chrono::month_day{birth.month(), birth.day()} >
        std::chrono::month_day{reference.month(), reference.day()}) {
        --age;
    }
    return age < 0 ? 0 : age;
}

template <std::ranges::input_range Dates>
    requires std::convertible_to<std::ranges::range_reference_t<Dates>, std::string_view>
std::vector<int> calculate_ages(const Dates& dates,
                                std::optional<std::chrono::year_month_day> reference = std::nullopt) {
    const std::chrono::year_month_day day = reference.value_or(today());
    std::vector<int> ages;
    ages.reserve(static_cast<std::size_t>(std::ranges::distance(dates)));
    for (const auto& text : dates) {
        ages.push_back(calculate_age(parse_date(std::string(std::string_view(text))), day));
    }
    return ages;
}

int main() {
    const std::vector<std::string> dates{"2000-01-01", "2010-05-15", "2020-12-31", "2025-01-01"};
    const std::chrono::year_month_day reference{std::chrono::year{2025}, std::chrono::month{6},
                                                std::chrono::day{1}};
    for (int age : calculate_ages(dates, reference)) {
        std::cout << age << ' ';
    }
    std::cout << '\n';
    return 0;
}
