```cpp
#include <iostream>
#include <iterator>
#include <string>
#include <utility>
#include <vector>

template <typename Iterator>
    requires std::forward_iterator<Iterator>
std::vector<std::pair<std::iter_value_t<Iterator>, int>> run_length_encoding(Iterator first,
                                                                             Iterator last) {
    std::vector<std::pair<std::iter_value_t<Iterator>, int>> runs;
    if (first == last) {
        return runs;
    }
    std::iter_value_t<Iterator> current = *first;
    int count = 1;
    for (Iterator iterator = std::next(first); iterator != last; ++iterator) {
        if (*iterator == current) {
            ++count;
        } else {
            runs.emplace_back(current, count);
            current = *iterator;
            count = 1;
        }
    }
    runs.emplace_back(current, count);
    return runs;
}

int main() {
    const std::vector<int> numbers{1, 1, 2, 2, 2, 3};
    for (const auto& [value, count] : run_length_encoding(numbers.begin(), numbers.end())) {
        std::cout << '(' << value << ',' << count << ") ";
    }
    std::cout << '\n';
    const std::string text = "aaabbbcc";
    std::cout << run_length_encoding(text.begin(), text.end()).size() << '\n';
    std::cout << run_length_encoding(numbers.begin(), numbers.begin()).size() << '\n';
    return 0;
}
