#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string_view>
#include <vector>

int edit_distance(std::string_view left, std::string_view right) {
    const std::size_t left_size = left.size();
    const std::size_t right_size = right.size();
    std::vector<std::size_t> previous(right_size + 1);
    std::vector<std::size_t> current(right_size + 1);
    for (std::size_t column = 0; column <= right_size; ++column) {
        previous[column] = column;
    }
    for (std::size_t row = 1; row <= left_size; ++row) {
        current[0] = row;
        for (std::size_t column = 1; column <= right_size; ++column) {
            const std::size_t cost = left[row - 1] == right[column - 1] ? 0u : 1u;
            current[column] = std::min({previous[column] + 1, current[column - 1] + 1,
                                        previous[column - 1] + cost});
        }
        previous.swap(current);
    }
    return static_cast<int>(previous[right_size]);
}

int main() {
    std::cout << edit_distance("kitten", "sitting") << '\n';
    std::cout << edit_distance("", "") << '\n';
    std::cout << edit_distance("abc", "") << '\n';
    return 0;
}
```

