#include <iostream>
#include <iterator>
#include <string>
#include <unordered_map>
#include <vector>

template <typename Iterator>
    requires std::input_iterator<Iterator>
bool is_parentheses_balanced(Iterator first, Iterator last,
                             const std::unordered_map<char, char>& bracket_map) {
    std::unordered_map<char, char> closing;
    for (const auto& [open, close] : bracket_map) {
        closing[close] = open;
    }
    std::vector<char> stack;
    for (Iterator iterator = first; iterator != last; ++iterator) {
        const char character = static_cast<char>(*iterator);
        if (bracket_map.contains(character)) {
            stack.push_back(character);
        } else if (closing.contains(character)) {
            if (stack.empty() || stack.back() != closing.at(character)) {
                return false;
