```cpp
#include <cctype>
#include <iostream>
#include <limits>
#include <string>
#include <unordered_map>

int parse_duration(const std::string& input, const std::unordered_map<std::string, int>& units) {
    if (input.empty()) {
        return 0;
    }
    long long total = 0;
    std::size_t index = 0;
    while (index < input.size()) {
        if (std::isdigit(static_cast<unsigned char>(input[index])) == 0) {
            return 0;
        }
        long long number = 0;
        while (index < input.size() &&
               std::isdigit(static_cast<unsigned char>(input[index])) != 0) {
            number = number * 10 + (input[index] - '0');
            ++index;
            if (number > 1000000000LL) {
                return 0;
            }
        }
        const std::size_t unit_start = index;
        while (index < input.size() && std::isalpha(static_cast<unsigned char>(input[index])) != 0) {
            ++index;
        }
        if (unit_start == index) {
            return 0;
        }
        const auto found = units.find(input.substr(unit_start, index - unit_start));
        if (found == units.end()) {
            return 0;
        }
        total += number * found->second;
        if (total > std::numeric_limits<int>::max()) {
            return 0;
        }
    }
    return static_cast<int>(total);
}

int main() {
    const std::unordered_map<std::string, int> units{{"h", 3600}, {"m", 60}, {"s", 1}};
    for (const std::string& text : {"1h30m", "2h45m30s", "invalid", "123"}) {
        std::cout << text << " -> " << parse_duration(text, units) << '\n';
    }
    return 0;
}
