#include <algorithm>
#include <cstddef>
#include <iostream>
#include <iterator>
#include <ranges>
#include <vector>

template <typename Iterator>
    requires std::forward_iterator<Iterator>
          && std::ranges::forward_range<std::iter_value_t<Iterator>>
std::vector<std::vector<std::ranges::range_value_t<std::iter_value_t<Iterator>>>> transpose(
    Iterator first, Iterator last) {
    using row_type = std::iter_value_t<Iterator>;
    using value_type = std::ranges::range_value_t<row_type>;
    std::vector<std::vector<value_type>> rows;
    for (Iterator iterator = first; iterator != last; ++iterator) {
        rows.emplace_back(iterator->begin(), iterator->end());
    }
    if (rows.empty()) {
        return {};
    }
    std::size_t columns = rows.front().size();
    for (const std::vector<value_type>& row : rows) {
        columns = std::min(columns, row.size());
    }
    std::vector<std::vector<value_type>> result(columns, std::vector<value_type>(rows.size()));
    for (std::size_t row = 0; row < rows.size(); ++row) {
        for (std::size_t column = 0; column < columns; ++column) {
            result[column][row] = rows[row][column];
        }
    }
    return result;
}

int main() {
    const std::vector<std::vector<int>> matrix{{1, 2, 3}, {4, 5, 6}, {7, 8}};
    for (const std::vector<int>& row : transpose(matrix.begin(), matrix.end())) {
        for (int value : row) {
            std::cout << value << ' ';
        }
        std::cout << '\n';
    }
    return 0;
}
