#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>

template <std::ranges::input_range Fields>
    requires std::convertible_to<std::ranges::range_reference_t<Fields>, std::string_view>
std::string to_csv_row(const Fields& fields) {
    std::string result;
    bool first = true;
    for (const auto& field : fields) {
        const std::string_view view(field);
        if (!first) {
            result.push_back(',');
