        result.push_back('"');
        for (char character : view) {
            if (character == '"') {
                result.push_back('"');
            }
            result.push_back(character);
        }
        result.push_back('"');
    }
    return result;
}

int main() {
    const std::vector<std::string> fields{"Name", "Hello, World", "say \"hi\"", "plain"};
    std::cout << to_csv_row(fields) << '\n';
