#include <iterator>
#include <utility>
#include <vector>

template <typename FirstIterator, typename SecondIterator>
    requires std::forward_iterator<FirstIterator> && std::forward_iterator<SecondIterator>
std::vector<std::pair<std::iter_value_t<FirstIterator>, std::iter_value_t<SecondIterator>>>
cartesian_product(FirstIterator first1, FirstIterator last1, SecondIterator first2,
                  SecondIterator last2) {
    using first_type = std::iter_value_t<FirstIterator>;
    using second_type = std::iter_value_t<SecondIterator>;
    std::vector<std::pair<first_type, second_type>> result;
    for (FirstIterator left = first1; left != last1; ++left) {
        for (SecondIterator right = first2; right != last2; ++right) {
            result.emplace_back(*left, *right);
        }
    }
    return result;
}

int main() {
