    const std::vector<char> letters{'a', 'b'};
    for (const auto& [number, letter] : cartesian_product(numbers.begin(), numbers.end(),
                                                         letters.begin(), letters.end())) {
        std::cout << '(' << number << ',' << letter << ") ";
    }
    std::cout << '\n';
    const std::vector<int> empty_values{};
    std::cout << cartesian_product(numbers.begin(), numbers.end(), empty_values.begin(),
                                   empty_values.end())
