```cpp
#include <cctype>
#include <iostream>
#include <string>
#include <string_view>
#include <utility>

std::pair<int, int> parseDimension(const std::string& input) {
    const std::string_view text(input);
    const auto x_pos = text.find('x');
    if (x_pos == std::string_view::npos) {
        return {0, 0};
    }
    const auto parse_side = [](std::string_view side) -> int {
        while (!side.empty() && std::isspace(static_cast<unsigned char>(side.front()))) {
            side.remove_prefix(1);
        }
        while (!side.empty() && std::isspace(static_cast<unsigned char>(side.back()))) {
            side.remove_suffix(1);
        }
        if (side.empty() || side.size() > 9) {
            return -1;
        }
        int value = 0;
        for (const char symbol : side) {
            if (!std::isdigit(static_cast<unsigned char>(symbol))) {
                return -1;
            }
            value = value * 10 + (symbol - '0');
        }
        return value;
    };
    const int width = parse_side(text.substr(0, x_pos));
    const int height = parse_side(text.substr(x_pos + 1));
    if (width <= 0 || height <= 0) {
        return {0, 0};
    }
    return {width, height};
}

int main() {
    for (const std::string& text : {std::string("800x600"), std::string("800 x 600"), std::string("abcx123")}) {
        const auto [width, height] = parseDimension(text);
        std::cout << width << 'x' << height << std::endl;
    }
    return 0;
}
