#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>

namespace {

std::string trim(std::string_view text) {
    const auto first = text.find_first_not_of(" \t\r\n");
    if (first == std::string_view::npos) {
        return {};
    }
    const auto last = text.find_last_not_of(" \t\r\n");
    return std::string(text.substr(first, last - first + 1));
}

}

std::unordered_map<std::string, std::string> parseKeyValue(std::string_view line) {
    std::unordered_map<std::string, std::string> result;
    const auto first = line.find_first_not_of(" \t\r\n");
    if (first == std::string_view::npos || line[first] == '#') {
        return result;
    }
    line.remove_prefix(first);
    const auto equals = line.find('=');
    if (equals == std::string_view::npos) {
        return result;
    }
    const std::string key = trim(line.substr(0, equals));
    if (key.empty()) {
        return result;
    }
    result.emplace(key, trim(line.substr(equals + 1)));
    return result;
}

template <std::ranges::input_range Lines>
    requires std::convertible_to<std::ranges::range_value_t<Lines>, std::string_view>
std::unordered_map<std::string, std::string> parseKeyValueLines(Lines&& lines) {
    std::unordered_map<std::string, std::string> result;
    for (auto&& line : lines) {
        for (const auto& [key, value] : parseKeyValue(std::string_view(line))) {
            result.insert_or_assign(key, value);
        }
    }
    return result;
}

int main() {
    const std::vector<std::string> lines{"name=John", "age=30", "# comment", "name=Jane"};
    for (const auto& [key, value] : parseKeyValueLines(lines)) {
        std::cout << key << '=' << value << std::endl;
    }
    return 0;
}
