#include <functional>
#include <iostream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <utility>

class LazyCache {
public:
    explicit LazyCache(std::unordered_map<std::string, std::function<int()>> factories)
        : factories_(std::move(factories)) {}

    void add_to_cache(const std::string& key, std::function<int()> factory) {
        factories_.insert_or_assign(key, std::move(factory));
    }

    int cached_value(const std::string& key) {
        if (key.empty()) {
            throw std::invalid_argument("key must not be empty");
        }
        const auto cached = values_.find(key);
        if (cached != values_.end()) {
            return cached->second;
        }
        const auto factory = factories_.find(key);
        if (factory == factories_.end()) {
            throw std::out_of_range("unknown key: " + key);
        }
        const int value = factory->second();
        values_.emplace(key, value);
        return value;
    }

    bool is_cached(const std::string& key) const {
        return values_.find(key) != values_.end();
    }

private:
    std::unordered_map<std::string, std::function<int()>> factories_;
    std::unordered_map<std::string, int> values_;
};

int main() {
    LazyCache cache{{{"factorial", [] { return 5 * 4 * 3 * 2 * 1; }}}};
    cache.add_to_cache("square", [] { return 5 * 5; });
    std::cout << cache.cached_value("square") << ' ' << cache.is_cached("square") << std::endl;
    std::cout << cache.cached_value("factorial") << std::endl;
    try {
        std::cout << cache.cached_value("unknown") << std::endl;
    } catch (const std::out_of_range& error) {
        std::cout << error.what() << std::endl;
    }
    return 0;
}
```

