#include <concepts>
#include <cstddef>
#include <functional>
#include <iostream>
#include <optional>
#include <ranges>
#include <unordered_map>
#include <vector>

template <typename T>
concept hashable = requires(const T& value) {
    { std::hash<T>{}(value) } -> std::convertible_to<std::size_t>;
};

template <std::ranges::input_range Range>
    requires hashable<std::ranges::range_value_t<Range>> &&
             std::equality_comparable<std::ranges::range_value_t<Range>>
std::optional<std::ranges::range_value_t<Range>> find_mode(Range&& values) {
    using Value = std::ranges::range_value_t<Range>;
    std::unordered_map<Value, std::size_t> frequency;
    for (auto&& value : values) {
        ++frequency[value];
    }
    if (frequency.empty()) {
        return std::nullopt;
    }
    auto best = frequency.begin();
    for (auto it = frequency.begin(); it != frequency.end(); ++it) {
        if (it->second > best->second) {
            best = it;
        }
    }
    return best->first;
}

int main() {
    const std::vector<int> values{1, 2, 2, 3, 3, 3};
    std::cout << find_mode(values).value_or(-1) << std::endl;
    std::cout << find_mode(std::vector<int>{}).has_value() << std::endl;
    return 0;
}
