#include <concepts>
#include <cstddef>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>

namespace {

constexpr char CR = '\r';
constexpr char LF = '\n';
constexpr std::string_view CRLF = "\r\n";

}

template <std::ranges::input_range Segments>
    requires std::convertible_to<std::ranges::range_reference_t<Segments>, std::string_view>
std::vector<std::string> normalize_newlines(Segments&& segments) {
    std::vector<std::string> result;
    for (auto&& segment : segments) {
        const std::string_view text(segment);
        std::string normalized;
        normalized.reserve(text.size());
        for (std::size_t i = 0; i < text.size(); ++i) {
            if (text.substr(i, CRLF.size()) == CRLF) {
                normalized.push_back(LF);
                ++i;
            } else if (text[i] == CR) {
                normalized.push_back(LF);
            } else {
                normalized.push_back(text[i]);
            }
        }
        result.push_back(normalized);
    }
    return result;
}

int main() {
    const std::vector<std::string> segments{"Hello\r\nWorld", "a\rb", ""};
    for (const auto& line : normalize_newlines(segments)) {
        std::cout << line.size() << std::endl;
    }
    return 0;
}
