#include <concepts>
#include <cstddef>
#include <iostream>
#include <ranges>
#include <vector>

template <std::ranges::input_range Range>
    requires std::convertible_to<std::ranges::range_reference_t<Range>, double>
std::vector<double> calculateDifference(Range&& values) {
    std::vector<double> data;
    for (auto&& value : values) {
        data.emplace_back(static_cast<double>(value));
    }
    std::vector<double> result;
    if (data.size() < 2) {
        return result;
    }
    result.reserve(data.size() - 1);
    for (std::size_t i = 1; i < data.size(); ++i) {
        result.push_back(data[i] - data[i - 1]);
    }
    return result;
}

int main() {
    const std::vector<double> data{1.0, 3.0, 5.0, 7.0};
    for (const double step : calculateDifference(data)) {
        std::cout << step << ' ';
    }
    std::cout << std::endl;
    return 0;
}
