#include <concepts>
#include <cstddef>
#include <iostream>
#include <ranges>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

template <std::ranges::input_range Lines>
    requires std::convertible_to<std::ranges::range_reference_t<Lines>, std::string_view>
std::vector<std::string> reindent(Lines&& lines, int step) {
    if (step < 0) {
        throw std::invalid_argument("step must not be negative");
    }
    std::vector<std::string> result;
    for (auto&& line : lines) {
        const std::string_view text(line);
        std::size_t index = 0;
        std::string expanded;
        while (index < text.size() && (text[index] == ' ' || text[index] == '\t')) {
            if (text[index] == '\t') {
                expanded.append(static_cast<std::size_t>(step), ' ');
            } else {
                expanded.push_back(' ');
            }
            ++index;
        }
        if (index == text.size()) {
            result.emplace_back();
            continue;
        }
        expanded.append(text.substr(index));
        result.push_back(expanded);
    }
    return result;
}

int main() {
    const std::vector<std::string> lines{"root", "  child", "\tgrandchild", ""};
    for (const auto& line : reindent(lines, 4)) {
        std::cout << '[' << line << ']' << std::endl;
    }
    return 0;
}
