#include <string_view>
#include <vector>

std::string quoteCommand(const std::string& argument) {
    bool needs_quote = false;
    for (const char symbol : argument) {
        if (std::isspace(static_cast<unsigned char>(symbol)) || std::iscntrl(static_cast<unsigned char>(symbol))
            || symbol == '\'' || symbol == '"' || symbol == '|' || symbol == '&' || symbol == ';'
            || symbol == '(' || symbol == ')' || symbol == '<' || symbol == '>' || symbol == '$' || symbol == '`') {
            needs_quote = true;
            break;
        }
    }
    if (!needs_quote) {
        return argument;
    }
    std::string escaped;
    escaped.reserve(argument.size() + 2);
    escaped.push_back('"');
    for (const char symbol : argument) {
        if (symbol == '"' || symbol == '\\' || symbol == '$' || symbol == '`') {
            escaped.push_back('\\');
        }
        escaped.push_back(symbol);
    }
    escaped.push_back('"');
    return escaped;
}

template <std::ranges::input_range Args>
    requires std::convertible_to<std::ranges::range_reference_t<Args>, std::string_view>
std::string joinCommands(Args&& args) {
    std::string command;
    for (auto&& argument : args) {
        const std::string quoted = quoteCommand(std::string(argument));
        if (!command.empty()) {
            command.push_back(' ');
        }
        command += quoted;
    }
    return command;
}

int main() {
    const std::vector<std::string> args{"ls", "my file.txt", "a;b"};
    std::cout << joinCommands(args) << std::endl;
    std::cout << joinCommands(std::vector<std::string>{}).empty() << std::endl;
    return 0;
}
