#include <iostream>
#include <string>
#include <unordered_set>
#include <vector>

std::vector<std::filesystem::path> deduplicate_paths(const std::vector<std::filesystem::path>& paths) {
    std::vector<std::filesystem::path> result;
    std::unordered_set<std::string> seen;
    for (const auto& path : paths) {
        const std::filesystem::path resolved = std::filesystem::absolute(path).lexically_normal();
        if (seen.insert(resolved.string()).second) {
            result.push_back(resolved);
        }
    }
    return result;
}

int main() {
