#include <concepts>
#include <iostream>
#include <iterator>
#include <utility>
#include <vector>

template <std::forward_iterator Iterator>
    requires std::copyable<std::iter_value_t<Iterator>>
std::vector<std::pair<std::iter_value_t<Iterator>, std::iter_value_t<Iterator>>> pairwise(Iterator first, Iterator last) {
    using T = std::iter_value_t<Iterator>;
    std::vector<std::pair<T, T>> result;
    if (first == last) {
