#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <string>

std::string left_pad_zero(long long num, int width) {
    if (width < 0) {
        throw std::invalid_argument("width must not be negative");
    }
    std::string text = std::to_string(num);
    std::string sign;
    if (!text.empty() && text.front() == '-') {
        sign = "-";
        text.erase(0, 1);
    }
    const auto target = static_cast<std::size_t>(width);
    if (text.size() < target) {
        text.insert(0, target - text.size(), '0');
    }
    return sign + text;
}

int main() {
    std::cout << left_pad_zero(123, 5) << ' ' << left_pad_zero(-123, 5) << std::endl;
    std::cout << left_pad_zero(123456789, 5) << ' ' << left_pad_zero(0, 3) << std::endl;
    return 0;
}
