std::string block_read(const std::filesystem::path& path, std::size_t block_size) {
    if (block_size == 0) {
        throw std::invalid_argument("block size must be positive");
    }
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        throw std::runtime_error("cannot open file: " + path.string());
    }
    std::string block(block_size, '\0');
    file.read(block.data(), static_cast<std::streamsize>(block_size));
    block.resize(static_cast<std::size_t>(file.gcount()));
    return block;
}

std::vector<std::string> read_file_in_blocks(const std::filesystem::path& path, std::size_t block_size) {
    if (block_size == 0) {
        throw std::invalid_argument("block size must be positive");
    }
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        throw std::runtime_error("cannot open file: " + path.string());
    }
    std::vector<std::string> blocks;
    std::string buffer(block_size, '\0');
    while (file) {
        file.read(buffer.data(), static_cast<std::streamsize>(block_size));
        const auto count = static_cast<std::size_t>(file.gcount());
        if (count == 0) {
            break;
        }
        blocks.push_back(buffer.substr(0, count));
    }
    return blocks;
}

