### ✅ 示例代码：

```cpp
#include <iostream>
#include <map>
#include <string>

namespace {

const std::map<std::string, std::string> irregular_forms{
    {"child", "children"},
    {"man", "men"},
    {"woman", "women"},
    {"foot", "feet"},
    {"tooth", "teeth"},
    {"mouse", "mice"},
    {"goose", "geese"},
};

}

std::string pluralize(const std::string& word, int count) {
    if (count == 1 || word.empty()) {
        return word;
    }
    const auto irregular = irregular_forms.find(word);
    if (irregular != irregular_forms.end()) {
        return irregular->second;
    }
    const auto ends_with = [&word](const std::string& suffix) {
        return word.size() >= suffix.size()
            && word.compare(word.size() - suffix.size(), suffix.size(), suffix) == 0;
    };
    if (ends_with("s") || ends_with("x") || ends_with("z") || ends_with("ch") || ends_with("sh")) {
        return word + "es";
    }
    if (ends_with("y") && word.size() > 1) {
        const char before = word[word.size() - 2];
        const bool vowel = before == 'a' || before == 'e' || before == 'i' || before == 'o' || before == 'u';
        if (!vowel) {
            return word.substr(0, word.size() - 1) + "ies";
        }
    }
    if (ends_with("f")) {
        return word.substr(0, word.size() - 1) + "ves";
    }
    return word + "s";
}

int main() {
    std::cout << pluralize("child", 1) << ' ' << pluralize("child", 2) << std::endl;
    std::cout << pluralize("apple", 2) << ' ' << pluralize("box", 2) << ' ' << pluralize("city", 2) << std::endl;
    return 0;
}
