```cpp
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

std::string compute_fnv1a_64(const std::filesystem::path& path) {
    constexpr std::uint64_t offset_basis = 14695981039346656037ULL;
    constexpr std::uint64_t prime = 1099511628211ULL;
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        return {};
    }
    std::vector<char> buffer(8192);
    std::uint64_t hash = offset_basis;
    while (file) {
        file.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const auto count = static_cast<std::size_t>(file.gcount());
        for (std::size_t i = 0; i < count; ++i) {
            hash ^= static_cast<unsigned char>(buffer[i]);
            hash *= prime;
        }
    }
    static constexpr const char* digits = "0123456789abcdef";
    std::string encoded;
    encoded.reserve(16);
    for (int shift = 60; shift >= 0; shift -= 4) {
        encoded.push_back(digits[(hash >> shift) & 0x0F]);
    }
    return encoded;
}

int main() {
    const auto path = std::filesystem::temp_directory_path() / "demo_hash.bin";
    {
        std::ofstream out(path, std::ios::binary);
        out << "hello";
    }
    std::cout << compute_fnv1a_64(path) << std::endl;
    std::filesystem::remove(path);
    return 0;
}
```

