#include <algorithm>
#include <concepts>
#include <iostream>
#include <iterator>
#include <vector>

template <std::input_iterator Left, std::input_iterator Right>
    requires std::same_as<std::iter_value_t<Left>, std::iter_value_t<Right>>
        && std::copyable<std::iter_value_t<Left>>
std::vector<std::iter_value_t<Left>> mergeAndDeduplicate(Left first1, Left last1, Right first2, Right last2) {
    using T = std::iter_value_t<Left>;
    std::vector<T> result;
    for (Left it = first1; it != last1; ++it) {
        if (std::find(result.begin(), result.end(), *it) == result.end()) {
            result.push_back(*it);
        }
    }
    for (Right it = first2; it != last2; ++it) {
        if (std::find(result.begin(), result.end(), *it) == result.end()) {
            result.push_back(*it);
        }
    }
    return result;
}

int main() {
    const int left[]{1, 2, 3, 4, 2};
    const int right[]{3, 5, 2, 6};
    for (const int value : mergeAndDeduplicate(std::begin(left), std::end(left), std::begin(right), std::end(right))) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;
