using NestedMap = std::map<std::string, std::map<std::string, std::string>>;

std::string getValueByPath(const NestedMap& data, const std::string& path, const std::string& default_value = "") {
    const auto dot = path.find('.');
    if (dot == std::string::npos) {
        return default_value;
    }
    const auto outer = data.find(path.substr(0, dot));
    if (outer == data.end()) {
        return default_value;
    }
    const auto inner = outer->second.find(path.substr(dot + 1));
    if (inner == outer->second.end()) {
        return default_value;
    }
    return inner->second;
}

int main() {
