        {"d", {{"e", "value3"}}},
    };
    try {
        std::cout << getValueByPath(data, "a.b") << ' ' << getValueByPath(data, "a.x", "default") << std::endl;
    } catch (const std::out_of_range&) {
        std::cout << "unexpected out_of_range" << std::endl;
    }
    std::cout << getValueByPath(data, "f.g", "missing") << std::endl;
