#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>

template <std::ranges::input_range Words>
    requires std::convertible_to<std::ranges::range_reference_t<Words>, std::string_view>
std::string longestCommonPrefix(Words&& words) {
    std::string prefix;
    bool first_word = true;
    for (auto&& word : words) {
        const std::string_view current(word);
        if (first_word) {
            prefix.assign(current);
            first_word = false;
            continue;
        }
        if (current.empty()) {
            return {};
        }
        const std::size_t limit = prefix.size() < current.size() ? prefix.size() : current.size();
        std::size_t length = 0;
        while (length < limit && prefix[length] == current[length]) {
            ++length;
        }
        prefix.resize(length);
        if (prefix.empty()) {
            return {};
        }
    }
    return prefix;
}

int main() {
    const std::vector<std::string> words{"flower", "flow", "flight"};
    std::cout << longestCommonPrefix(words) << std::endl;
    std::cout << longestCommonPrefix(std::vector<std::string>{"abc", "", "def"}) << std::endl;
    return 0;
}
