#include <vector>

template <std::ranges::contiguous_range Text>
    requires std::same_as<std::ranges::range_value_t<Text>, char>
std::vector<std::pair<std::string, int>> countWordFrequency(Text&& text) {
    std::map<std::string, int> counts;
    std::string current;
    for (const char symbol : text) {
        if (std::isalpha(static_cast<unsigned char>(symbol))) {
            current.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(symbol))));
        } else if (!current.empty()) {
            ++counts[current];
            current.clear();
        }
    }
    if (!current.empty()) {
        ++counts[current];
    }
    std::vector<std::pair<std::string, int>> result;
    result.reserve(counts.size());
    for (const auto& [word, count] : counts) {
        result.emplace_back(word, count);
    }
    std::sort(result.begin(), result.end(), [](const auto& left, const auto& right) {
        if (left.second != right.second) {
            return left.second > right.second;
        }
        return left.first < right.first;
    });
    return result;
}

int main() {
    const std::string text = "Hello, world! Hello again.";
    for (const auto& [word, count] : countWordFrequency(text)) {
        std::cout << word << ':' << count << ' ';
    }
    std::cout << std::endl;
    return 0;
