```cpp
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <ranges>
#include <stdexcept>
#include <string>
#include <vector>

enum class Encoding {
    UTF8,
    UTF16,
    UTF32,
};

namespace {

void append_code_point(std::string& target, std::uint32_t code_point) {
    if (code_point <= 0x7F) {
        target.push_back(static_cast<char>(code_point));
        return;
    }
    const int length = code_point <= 0x7FF ? 2 : code_point <= 0xFFFF ? 3 : 4;
    std::string encoded(static_cast<std::size_t>(length), static_cast<char>(0x80));
    std::uint32_t value = code_point;
    for (int index = length - 1; index >= 1; --index) {
        encoded[static_cast<std::size_t>(index)] = static_cast<char>(0x80 | (value & 0x3F));
        value >>= 6;
    }
    encoded[0] = static_cast<char>(((0xFF << (8 - length)) & 0xFF) | static_cast<int>(value));
    target += encoded;
}

}

template <std::ranges::input_range Bytes>
    requires std::convertible_to<std::ranges::range_value_t<Bytes>, int>
std::string decode_bytes(Bytes&& bytes, Encoding encoding = Encoding::UTF8, char replacement = '?') {
    std::vector<std::uint8_t> data;
    for (auto&& value : bytes) {
        const int byte = static_cast<int>(value);
        if (byte < 0 || byte > 255) throw std::invalid_argument("byte out of range");
        data.push_back(static_cast<std::uint8_t>(byte));
    }
    std::string result;
    std::size_t index = 0;
    while (index < data.size()) {
        if (encoding == Encoding::UTF8) {
            const std::uint8_t lead = data[index];
            const std::size_t length = (lead & 0x80) == 0x00 ? 1 : (lead & 0xE0) == 0xC0 ? 2 : (lead & 0xF0) == 0xE0 ? 3 : (lead & 0xF8) == 0xF0 ? 4 : 0;
            std::uint32_t code_point = lead & (length == 1 ? 0x7F : length == 2 ? 0x1F : length == 3 ? 0x0F : 0x07);
            bool valid = length != 0 && index + length <= data.size();
            for (std::size_t offset = 1; valid && offset < length; ++offset) {
                const std::uint8_t continuation = data[index + offset];
                valid = (continuation & 0xC0) == 0x80;
                code_point = (code_point << 6) | (continuation & 0x3F);
            }
            const std::uint32_t minimum = length == 2 ? 0x80u : length == 3 ? 0x800u : length == 4 ? 0x10000u : 0u;
            if (!valid || code_point > 0x10FFFF || (code_point >= 0xD800 && code_point <= 0xDFFF)
                || code_point < minimum) {
                result.push_back(replacement);
                ++index;
                continue;
            }
            append_code_point(result, code_point);
            index += length;
        } else if (encoding == Encoding::UTF16) {
            if (index + 1 >= data.size()) { result.push_back(replacement); break; }
            std::uint32_t unit = data[index] | (static_cast<std::uint32_t>(data[index + 1]) << 8);
            std::size_t width = 2;
            if (unit >= 0xD800 && unit <= 0xDBFF && index + 3 < data.size()) {
                const std::uint32_t second = data[index + 2] | (static_cast<std::uint32_t>(data[index + 3]) << 8);
                if (second >= 0xDC00 && second <= 0xDFFF) {
                    unit = 0x10000 + ((unit - 0xD800) << 10) + (second - 0xDC00);
                    width = 4;
                }
            }
            if (unit >= 0xD800 && unit <= 0xDFFF) result.push_back(replacement);
            else append_code_point(result, unit);
            index += width;
        } else {
            if (index + 3 >= data.size()) { result.push_back(replacement); break; }
            const std::uint32_t code_point = data[index] | (static_cast<std::uint32_t>(data[index + 1]) << 8)
                | (static_cast<std::uint32_t>(data[index + 2]) << 16) | (static_cast<std::uint32_t>(data[index + 3]) << 24);
            if (code_point > 0x10FFFF || (code_point >= 0xD800 && code_point <= 0xDFFF)) {
                result.push_back(replacement);
                ++index;
            } else {
                append_code_point(result, code_point);
                index += 4;
            }
        }
    }
    return result;
}
```

