### ✅ 代码实现（`reservoir_sampling.cpp`）：

```cpp
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <iterator>
#include <random>
#include <vector>

template <std::input_iterator Iterator>
    requires std::copyable<std::iter_value_t<Iterator>>
std::vector<std::iter_value_t<Iterator>> reservoir_sampling(Iterator begin, Iterator end, int k, std::uint64_t seed = 0) {
    using T = std::iter_value_t<Iterator>;
    std::vector<T> result;
    if (k <= 0) {
        return result;
    }
    result.reserve(static_cast<std::size_t>(k));
    std::mt19937_64 engine(seed);
    int count = 0;
    for (Iterator it = begin; it != end; ++it, ++count) {
        if (count < k) {
            result.push_back(*it);
            continue;
        }
        std::uniform_int_distribution<int> distribution(0, count);
        const int slot = distribution(engine);
        if (slot < k) {
            result[static_cast<std::size_t>(slot)] = *it;
        }
    }
    return result;
}

int main() {
    const std::vector<int> data{1, 2, 3, 4, 5, 6, 7, 8};
    const auto first_run = reservoir_sampling(data.begin(), data.end(), 3, 42);
    const auto second_run = reservoir_sampling(data.begin(), data.end(), 3, 42);
    std::cout << (first_run == second_run) << ' ' << first_run.size() << std::endl;
    std::cout << reservoir_sampling(data.begin(), data.end(), 0).size() << std::endl;
    return 0;
}
```

