#include <algorithm>
#include <charconv>
#include <concepts>
#include <iostream>
#include <map>
#include <string>
#include <system_error>
#include <utility>
#include <vector>

template <typename Row>
concept map_row = std::ranges::input_range<Row> && requires(Row row) {
    typename std::ranges::range_value_t<Row>::first_type;
    typename std::ranges::range_value_t<Row>::second_type;
};

template <std::ranges::input_range Rows>
    requires map_row<std::ranges::range_value_t<Rows>>
std::vector<std::map<std::string, std::string>> sort_by_fields(Rows&& rows, const std::vector<std::string>& fields) {
    std::vector<std::map<std::string, std::string>> result;
    for (const auto& row : rows) {
        std::map<std::string, std::string> converted;
        for (const auto& entry : row) {
            converted.emplace(std::string(entry.first), std::string(entry.second));
        }
        result.push_back(std::move(converted));
    }
    const auto field_value = [](const std::map<std::string, std::string>& row, const std::string& field) -> int {
        const auto it = row.find(field);
        if (it == row.end()) {
            return 0;
        }
        int value = 0;
        const auto parsed = std::from_chars(it->second.data(), it->second.data() + it->second.size(), value);
        if (parsed.ec != std::errc{}) {
            return 0;
        }
        return value;
    };
    std::stable_sort(result.begin(), result.end(), [&fields, &field_value](const auto& left, const auto& right) {
        for (const auto& field : fields) {
            const int left_value = field_value(left, field);
            const int right_value = field_value(right, field);
            if (left_value != right_value) {
                return left_value < right_value;
            }
        }
        return false;
    });
    return result;
}

int main() {
    const std::vector<std::map<std::string, std::string>> rows{
        {{"a", "10"}, {"b", "20"}},
        {{"a", "5"}, {"b", "15"}},
        {{"b", "100"}},
    };
    for (const auto& row : sort_by_fields(rows, {"a", "b"})) {
        const auto first = row.find("a");
        const auto second = row.find("b");
        std::cout << (first == row.end() ? std::string("0") : first->second) << ' '
                  << (second == row.end() ? std::string("0") : second->second) << std::endl;
    }
    return 0;
}
