#include <cstddef>
#include <iostream>
#include <string>

std::string truncate_text(const std::string& text, int width) {
    if (width <= 0) {
        return {};
    }
    if (text.size() <= static_cast<std::size_t>(width)) {
        return text;
    }
    const std::size_t size = static_cast<std::size_t>(width);
    if (size <= 3) {
        return text.substr(0, size);
    }
    const std::size_t head = (size - 3) / 2;
    const std::size_t tail = size - 3 - head;
    return text.substr(0, head) + "..." + text.substr(text.size() - tail);
}

int main() {
    std::cout << truncate_text("Hello, world!", 5) << std::endl;
    std::cout << truncate_text("Short", 5) << std::endl;
    std::cout << truncate_text("Very long string", 0) << std::endl;
    return 0;
}
