- `Predict` 方法返回 `List<int>`，表示预测的类别标签。
- 只使用标准库，不依赖其他库。
- 包含 `Main` 方法用于演示。

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public sealed class KnnClassifier
{
    private readonly int _nNeighbors;
    private double[][]? _x;
    private int[]? _y;

    public KnnClassifier(int nNeighbors = 3)
    {
        if (nNeighbors <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(nNeighbors), "nNeighbors must be positive");
        }

        _nNeighbors = nNeighbors;
    }

    public KnnClassifier Fit(IEnumerable<double[]> data, IEnumerable<int> labels)
    {
        ArgumentNullException.ThrowIfNull(data);
        ArgumentNullException.ThrowIfNull(labels);

        var rows = data.ToArray();
        if (rows.Length == 0)
        {
            throw new ArgumentException("data must not be empty", nameof(data));
        }

        int features = rows[0].Length;
        if (features == 0)
        {
            throw new ArgumentException("rows must not be empty", nameof(data));
        }

        if (rows.Any(row => row.Length != features))
        {
            throw new ArgumentException("rows must share the same length", nameof(data));
        }

        _x = rows.Select(row => row.ToArray()).ToArray();
        _y = labels.ToArray();
        if (_x.Length != _y.Length)
        {
            throw new ArgumentException("data and labels must share the same length", nameof(labels));
        }

        return this;
    }

    public List<int> Predict(IEnumerable<double[]> samples, int? k = null)
    {
        ArgumentNullException.ThrowIfNull(samples);
        if (_x is null || _y is null)
        {
            throw new InvalidOperationException("KnnClassifier is not fitted");
        }

        int neighbors = Math.Min(Math.Max(k ?? _nNeighbors, 1), _x.Length);
        var predictions = new List<int>();
        foreach (var sample in samples)
        {
            if (sample is null || sample.Length != _x[0].Length)
            {
                throw new ArgumentException("sample has a wrong feature count", nameof(samples));
            }

            predictions.Add(FindNearestLabel(sample, neighbors));
        }

        return predictions;
    }

    private int FindNearestLabel(double[] sample, int k) =>
        _x!.Select((row, index) => (Index: index, Distance: EuclideanDistance(sample, row)))
            .OrderBy(pair => pair.Distance)
            .Take(k)
            .Select(pair => _y![pair.Index])
            .GroupBy(label => label)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .First()
            .Key;

    private double EuclideanDistance(double[] a, double[] b)
    {
        double sum = 0.0;
        for (int i = 0; i < a.Length; i++)
        {
            double diff = a[i] - b[i];
            sum += diff * diff;
        }

        return Math.Sqrt(sum);
    }
}

public static class Program
{
    public static void Main()
    {
        var data = new List<double[]>
        {
            new[] { 1.0, 2.0 },
            new[] { 2.0, 3.0 },
            new[] { 4.0, 5.0 },
        };

        var classifier = new KnnClassifier(1).Fit(data, new[] { 0, 1, 2 });
        var predictions = classifier.Predict(new List<double[]> { new[] { 3.0, 4.0 } });
        Console.WriteLine(string.Join(", ", predictions));
    }
}
```

下面是一个使用 C# (.NET 8) 编写的 `KMeans` 聚类类，支持 `maxIter`、`tol`、`randomState` 参数，处理空簇时随机重选中心，并实现 `Predict` 方法返回聚类标签。该类仅包含一个 `.cs` 文件，不使用任何第三方库，仅使用 .NET 标准库。

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public sealed class KMeans
{
    private readonly int _k;
    private readonly int _maxIter;
    private readonly double _tol;
    private readonly Random _random;
    private double[][]? _data;
    private double[][]? _centroids;

    public KMeans(int k, int maxIter = 100, double tol = 1e-4, int randomState = 0)
    {
        if (k <= 0) throw new ArgumentOutOfRangeException(nameof(k));
        if (maxIter <= 0) throw new ArgumentOutOfRangeException(nameof(maxIter));
        if (tol <= 0.0) throw new ArgumentOutOfRangeException(nameof(tol));
        _k = k;
        _maxIter = maxIter;
        _tol = tol;
        _random = new Random(randomState);
    }

    public void Fit(IEnumerable<double[]> data)
    {
        ArgumentNullException.ThrowIfNull(data);
        _data = CheckMatrix(data);
        if (_data.Length < _k) throw new ArgumentException("need at least k points", nameof(data));
        _centroids = InitializeCentroids();
        for (int iteration = 0; iteration < _maxIter; iteration++)
        {
            var labels = Enumerable.Range(0, _data.Length).Select(index => GetClosestCluster(_data[index])).ToArray();
            if (ComputeDistance(labels) <= _tol) break;
            _centroids = UpdateCentroids(labels);
        }
    }

    public List<int> Predict(IEnumerable<double[]> data)
    {
        ArgumentNullException.ThrowIfNull(data);
        if (_centroids is null) throw new InvalidOperationException("KMeans is not fitted");
        return CheckMatrix(data).Select(GetClosestCluster).ToList();
    }

    private static double[][] CheckMatrix(IEnumerable<double[]> data)
    {
        var rows = data.ToArray();
        if (rows.Length == 0) throw new ArgumentException("data is empty", nameof(data));
        if (rows[0].Length == 0 || rows.Any(row => row.Length != rows[0].Length)) throw new ArgumentException("bad row length", nameof(data));
        return rows.Select(row => row.ToArray()).ToArray();
    }

    private double[][] InitializeCentroids()
    {
        var indices = new HashSet<int>();
        while (indices.Count < _k) indices.Add(_random.Next(_data!.Length));
        return indices.Select(index => _data![index].ToArray()).ToArray();
    }

    private double[][] UpdateCentroids(int[] labels)
    {
        var centroids = new double[_k][];
        for (int cluster = 0; cluster < _k; cluster++)
        {
            var members = Enumerable.Range(0, _data!.Length).Where(index => labels[index] == cluster).ToArray();
            if (members.Length == 0)
            {
                centroids[cluster] = _data![_random.Next(_data.Length)].ToArray();
                continue;
            }

            centroids[cluster] = Enumerable.Range(0, _data![0].Length)
                .Select(f => members.Average(index => _data[index][f]))
                .ToArray();
        }

        return centroids;
    }

    private double ComputeDistance(int[] labels)
    {
        double total = 0.0;
        for (int i = 0; i < _data!.Length; i++) total += EuclideanDistance(_data[i], _centroids![labels[i]]);
        return total;
    }

    private int GetClosestCluster(double[] point)
    {
        int closest = 0;
        double best = double.MaxValue;
        for (int cluster = 0; cluster < _k; cluster++)
        {
            double distance = EuclideanDistance(point, _centroids![cluster]);
            if (distance < best)
            {
                best = distance;
                closest = cluster;
            }
        }

        return closest;
    }

    private double EuclideanDistance(double[] a, double[] b)
    {
        if (a.Length != b.Length) throw new ArgumentException("length mismatch");
        double sum = 0.0;
        for (int i = 0; i < a.Length; i++) sum += (a[i] - b[i]) * (a[i] - b[i]);
        return Math.Sqrt(sum);
    }
}
```

以下是一个使用 C#（.NET 8）实现的 **Fuzzy C-Means (FCM)** 聚类算法的类，支持以下功能：

- 隶属度指数 $ m > 1 $
- 支持 `maxIter`（最大迭代次数）、`tol`（收敛容忍度）、`randomState`（随机种子）
- `Fit` 方法记录隶属度矩阵和硬标签
- `Predict` 方法返回预测的硬标签（`List<int>`）
- 使用标准库（不依赖外部库）

---

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public sealed class FuzzyCMeans
{
    private readonly int _nClusters;
    private readonly double _m;
    private readonly int _maxIter;
    private readonly double _tol;
    private readonly Random _random;
    private double[][]? _data;
    private double[][]? _centroids;
    private double[][]? _membership;
    private int[]? _hardLabels;

    public FuzzyCMeans(int nClusters, double m = 2.0, int maxIter = 100, double tol = 1e-4, int randomState = 0)
    {
        if (nClusters <= 0 || maxIter <= 0 || tol <= 0.0) throw new ArgumentOutOfRangeException(nameof(nClusters));
        if (m <= 1.0) throw new ArgumentException("m must be greater than 1", nameof(m));
        _nClusters = nClusters;
        _m = m;
        _maxIter = maxIter;
        _tol = tol;
        _random = new Random(randomState);
    }

    public int[] HardLabels => _hardLabels ?? Array.Empty<int>();

    public IReadOnlyList<double[]> Membership => _membership ?? Array.Empty<double[]>();

    public void Fit(IEnumerable<double[]> data)
    {
        ArgumentNullException.ThrowIfNull(data);
        _data = CheckMatrix(data);
        if (_data.Length < _nClusters) throw new ArgumentException("too few points", nameof(data));
        _centroids = Enumerable.Range(0, _nClusters).Select(_ => _data[_random.Next(_data.Length)].ToArray()).ToArray();
        _membership = _data.Select(_ => Enumerable.Repeat(1.0 / _nClusters, _nClusters).ToArray()).ToArray();
        double previous = double.MaxValue;
        for (int iteration = 0; iteration < _maxIter; iteration++)
        {
            ComputeCentroids();
            ComputeMembership();
            double current = _data.Select((row, index) => Enumerable.Range(0, _nClusters)
                .Sum(c => Math.Pow(_membership![index][c], _m) * SumSquares(row, _centroids![c]))).Sum();
            if (Math.Abs(current - previous) < _tol) break;
            previous = current;
        }

        _hardLabels = Enumerable.Range(0, _data.Length).Select(GetHardLabel).ToArray();
    }

    public List<int> Predict(IEnumerable<double[]> data)
    {
        ArgumentNullException.ThrowIfNull(data);
        if (_centroids is null || _membership is null) throw new InvalidOperationException("not fitted");
        return CheckMatrix(data).Select(point => Enumerable.Range(0, _nClusters)
            .OrderBy(c => SumSquares(point, _centroids![c])).First()).ToList();
    }

    private static double[][] CheckMatrix(IEnumerable<double[]> data)
    {
        var rows = data.ToArray();
        if (rows.Length == 0) throw new ArgumentException("data is empty", nameof(data));
        if (rows.Any(row => row.Length != rows[0].Length)) throw new ArgumentException("bad row length", nameof(data));
        return rows.Select(row => row.ToArray()).ToArray();
    }

    private void ComputeCentroids()
    {
        for (int c = 0; c < _nClusters; c++)
        {
            var weights = _data!.Select((row, index) => Math.Pow(_membership![index][c], _m)).ToArray();
            double weightSum = weights.Sum();
            _centroids![c] = Enumerable.Range(0, _data[0].Length)
                .Select(f => weightSum <= 0.0 ? 0.0 : _data.Select((item, j) => weights[j] * item[f]).Sum() / weightSum)
                .ToArray();
        }
    }

    private void ComputeMembership()
    {
        for (int i = 0; i < _data!.Length; i++)
        {
            for (int c = 0; c < _nClusters; c++)
            {
                double own = SumSquares(_data[i], _centroids![c]);
                if (own <= 1e-12)
                {
                    _membership![i][c] = 1.0;
                    continue;
                }

                double sum = Enumerable.Range(0, _nClusters).Sum(j => Math.Pow(own / SumSquares(_data[i], _centroids[j]), 1.0 / (_m - 1.0)));
                _membership![i][c] = 1.0 / sum;
            }
        }
    }

    private int GetHardLabel(int sampleIndex) =>
        Enumerable.Range(0, _nClusters).OrderByDescending(c => _membership![sampleIndex][c]).First();

    private static double SumSquares(double[] a, double[] b)
    {
        if (a.Length != b.Length) throw new ArgumentException("length mismatch");
        double sum = 0.0;
        for (int i = 0; i < a.Length; i++) sum += (a[i] - b[i]) * (a[i] - b[i]);
        return sum;
    }
}
```

