```csharp
using System;
using System.Collections.Generic;

public static class Deduplicator
{
    public static List<T> Deduplicate<T, TKey>(IEnumerable<T> source, Func<T, TKey> keySelector)
    {
        ArgumentNullException.ThrowIfNull(keySelector);

        var result = new List<T>();
        if (source is null)
        {
            return result;
        }

        var seen = new HashSet<TKey>();
        foreach (var item in source)
        {
            if (seen.Add(keySelector(item)))
            {
                result.Add(item);
            }
        }

        return result;
    }
}

public sealed class Person
{
    public string Name { get; init; } = string.Empty;

    public int Age { get; init; }

    public override string ToString() => $"Name: {Name}, Age: {Age}";
}

public static class Program
{
    public static void Main()
    {
        var data = new List<Person>
        {
            new Person { Name = "Alice", Age = 30 },
            new Person { Name = "Bob", Age = 25 },
            new Person { Name = "Alice", Age = 30 },
            new Person { Name = "Charlie", Age = 35 },
        };

        foreach (var person in Deduplicator.Deduplicate(data, person => person.Name))
        {
            Console.WriteLine(person);
        }

        foreach (var person in Deduplicator.Deduplicate(data, person => person.Age))
        {
            Console.WriteLine(person);
        }
    }
}
