```csharp
using System;

public static class Program
{
    public static string TruncateString(string input, int width)
    {
        ArgumentNullException.ThrowIfNull(input);
        if (input.Length == 0 || width <= 0)
        {
            return string.Empty;
        }

        int used = 0;
        int index = 0;
        while (index < input.Length)
        {
            int charWidth = IsFullWidth(input[index]) ? 2 : 1;
            if (used + charWidth > width)
            {
                break;
            }

            used += charWidth;
            index++;
        }

        return input.Substring(0, index);
    }

    private static bool IsFullWidth(char value)
    {
        int code = value;
        return (code >= 0x1100 && code <= 0x115F)
            || (code >= 0x2E80 && code <= 0xA4CF)
            || (code >= 0xFF01 && code <= 0xFF60)
            || (code >= 0xFFE0 && code <= 0xFFE6);
    }

    public static void Main()
    {
        Console.WriteLine(TruncateString("Hello, world!", 6));
        Console.WriteLine(TruncateString("Ｆｕｌｌｗｉｄｔｈ", 7));
        Console.WriteLine(TruncateString("1234567890", 5));
        Console.WriteLine(TruncateString("Hello", 0));
    }
}
