using System;
using System.IO;
using System.Text;

public static class Program
{
    public static bool AtomicWriteTextFile(string filePath, string content)
    {
        ArgumentNullException.ThrowIfNull(filePath);
        ArgumentNullException.ThrowIfNull(content);

        string? directory = Path.GetDirectoryName(filePath);
        if (string.IsNullOrEmpty(directory))
        {
            directory = Directory.GetCurrentDirectory();
        }

        if (!Directory.Exists(directory))
        {
            return false;
        }

        string tempPath = Path.Combine(directory, Path.GetRandomFileName());
        try
        {
            File.WriteAllText(tempPath, content, new UTF8Encoding(false));
            File.Move(tempPath, filePath, true);
            return true;
        }
        catch (IOException)
        {
            return false;
        }
        catch (UnauthorizedAccessException)
        {
            return false;
        }
        finally
        {
            if (File.Exists(tempPath))
            {
                File.Delete(tempPath);
            }
        }
    }

    public static void Main()
    {
        string filePath = Path.Combine(Path.GetTempPath(), "atomic-demo.txt");
        string content = "Hello" + Environment.NewLine + "UTF-8 encoded content.";
        Console.WriteLine(AtomicWriteTextFile(filePath, content));
    }
}
