```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public static class Program
{
    public static List<T> RemoveDuplicates<T>(IEnumerable<T> source) where T : IEquatable<T>
    {
        var result = new List<T>();
        if (source is null)
        {
            return result;
        }

        foreach (var item in source)
        {
            if (!result.Any(existing => Equals(existing, item)))
            {
                result.Add(item);
            }
        }

        return result;
    }

    public static void Main()
    {
        var numbers = new List<int> { 1, 2, 3, 2, 4, 1, 5 };
        var words = new List<string> { "a", "b", "a", "c", "b" };
        Console.WriteLine(string.Join(", ", RemoveDuplicates(numbers)));
        Console.WriteLine(string.Join(", ", RemoveDuplicates(words)));
        Console.WriteLine(RemoveDuplicates(new List<int>()).Count);
    }
}
