```csharp
using System;
using System.Collections.Generic;

public static class Program
{
    public static Dictionary<TKey, List<T>> GroupBy<TKey, T>(IEnumerable<T> source, Func<T, TKey> keySelector)
        where TKey : notnull
    {
        ArgumentNullException.ThrowIfNull(keySelector);

        var result = new Dictionary<TKey, List<T>>();
        if (source is null)
        {
            return result;
        }

        foreach (var item in source)
        {
            TKey key = keySelector(item);
            if (!result.TryGetValue(key, out var bucket))
            {
                bucket = new List<T>();
                result[key] = bucket;
            }

            bucket.Add(item);
        }

        return result;
    }

    public static void Main()
    {
        var numbers = new List<int> { 1, 2, 2, 3, 3, 3, 4 };
        foreach (var group in GroupBy(numbers, number => number % 2 == 0 ? "Even" : "Odd"))
        {
            Console.WriteLine($"Key: {group.Key}, Values: {string.Join(", ", group.Value)}");
        }

        var words = new List<string> { "apple", "banana", "pear", "kiwi", "grape" };
        foreach (var group in GroupBy(words, word => word.Length))
        {
            Console.WriteLine($"Key: {group.Key}, Values: {string.Join(", ", group.Value)}");
        }

        Console.WriteLine(GroupBy(new List<int>(), number => number).Count);
    }
}
