using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static string GenerateUrlSlug(IEnumerable<string> fragments)
    {
        if (fragments is null)
        {
            return string.Empty;
        }

        string combined = string.Join(" ", fragments).ToLowerInvariant();
        var builder = new StringBuilder(combined.Length);
        bool separatorPending = false;
        foreach (char c in combined)
        {
            if (char.IsLetterOrDigit(c))
            {
                if (separatorPending && builder.Length > 0)
                {
                    builder.Append('-');
                }

                builder.Append(c);
                separatorPending = false;
            }
            else if (builder.Length > 0)
            {
                separatorPending = true;
            }
        }

        return builder.ToString();
    }

    public static void Main()
    {
        var fragments = new List<string> { "Hello, World!", "C# is cool", "12345" };
        Console.WriteLine(GenerateUrlSlug(fragments));
        Console.WriteLine(GenerateUrlSlug(new List<string>()) == string.Empty);
    }
}
