using System;
using System.Collections.Generic;
using System.IO;

public static class Program
{
    public static List<string> FindFilesBySuffix(string rootDirectory, params string[] extensions)
    {
        var result = new List<string>();
        if (string.IsNullOrEmpty(rootDirectory) || !Directory.Exists(rootDirectory))
        {
            return result;
        }

        ArgumentNullException.ThrowIfNull(extensions);
        var suffixes = new HashSet<string>(extensions, StringComparer.OrdinalIgnoreCase);
        FindFilesRecursive(rootDirectory, suffixes, result);
        result.Sort(StringComparer.Ordinal);
        return result;
    }

    private static void FindFilesRecursive(string directoryPath, HashSet<string> suffixes, List<string> result)
    {
        try
        {
            foreach (string file in Directory.GetFiles(directoryPath))
            {
                if (suffixes.Contains(Path.GetExtension(file)))
                {
                    result.Add(file);
                }
            }

            foreach (string subDirectory in Directory.GetDirectories(directoryPath))
            {
                FindFilesRecursive(subDirectory, suffixes, result);
            }
        }
        catch (IOException)
        {
        }
        catch (UnauthorizedAccessException)
        {
        }
    }

    public static void Main()
    {
        string root = Directory.GetCurrentDirectory();
        foreach (string file in FindFilesBySuffix(root, ".cs"))
        {
            Console.WriteLine(file);
        }

        Console.WriteLine(FindFilesBySuffix("/no-such-directory", ".cs").Count);
    }
