```csharp
using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static List<string> ConvertToSnakeCase(IEnumerable<string> input)
    {
        var result = new List<string>();
        if (input is null) return result;
        foreach (var item in input)
        {
            if (string.IsNullOrEmpty(item))
            {
                result.Add(item);
                continue;
            }

            var builder = new StringBuilder(item.Length + 4);
            for (int i = 0; i < item.Length; i++)
            {
                char current = item[i];
                if (char.IsUpper(current))
                {
                    bool afterLowerOrDigit = i > 0 && !char.IsUpper(item[i - 1]);
                    bool acronymTail = i > 0 && char.IsUpper(item[i - 1]) && i + 1 < item.Length && char.IsLower(item[i + 1]);
                    if (afterLowerOrDigit || acronymTail) builder.Append('_');
                    builder.Append(char.ToLowerInvariant(current));
                }
                else
                {
                    builder.Append(current);
                }
            }

            result.Add(builder.ToString());
        }

        return result;
    }

    public static void Main()
    {
        var input = new List<string> { "CamelCase", "MyVariableName", "HTTPStatus404", "1234" };
        foreach (string word in ConvertToSnakeCase(input)) Console.WriteLine(word);
    }
}
