using System;
using System.Collections.Generic;
using System.IO;

public static class Program
{
    public static Dictionary<string, string> ReadConfigFile(string filePath)
    {
        ArgumentNullException.ThrowIfNull(filePath);
        var config = new Dictionary<string, string>();
        if (filePath.Length == 0 || !File.Exists(filePath)) return config;

        string[] lines;
        try
        {
            lines = File.ReadAllLines(filePath);
        }
        catch (IOException)
        {
            return config;
        }
        catch (UnauthorizedAccessException)
        {
            return config;
        }

        foreach (string rawLine in lines)
        {
            string line = rawLine.Trim();
            int equalsIndex = line.IndexOf('=');
            if (equalsIndex <= 0 || equalsIndex == line.Length - 1) continue;
            string key = line.Substring(0, equalsIndex).Trim();
            string value = line.Substring(equalsIndex + 1).Trim();
            if (key.Length > 0 && value.Length > 0) config[key] = value;
        }

        return config;
    }
}
