using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static List<string> SplitIdentifiers(IEnumerable<string> identifiers)
    {
        ArgumentNullException.ThrowIfNull(identifiers);
        var result = new List<string>();
        foreach (var identifier in identifiers)
        {
            if (string.IsNullOrEmpty(identifier)) continue;
            var current = new StringBuilder();
            for (int i = 0; i < identifier.Length; i++)
            {
                char symbol = identifier[i];
                if (symbol == '_' || !char.IsLetterOrDigit(symbol))
                {
                    FlushWord(current, result);
                    continue;
                }

                if (char.IsUpper(symbol) && current.Length > 0)
                {
                    char previous = current[current.Length - 1];
                    bool afterLowerOrDigit = !char.IsUpper(previous);
                    bool acronymTail = char.IsUpper(previous) && i + 1 < identifier.Length && char.IsLower(identifier[i + 1]);
                    if (afterLowerOrDigit || acronymTail) FlushWord(current, result);
                }

                current.Append(symbol);
            }

            FlushWord(current, result);
        }

        return result;
    }

    private static void FlushWord(StringBuilder current, List<string> result)
    {
        if (current.Length == 0) return;
        result.Add(current.ToString());
        current.Clear();
    }

    public static void Main()
    {
        var identifiers = new List<string> { "My_Variable_Name", "Hello World", "aBcDef", "HTTPStatus404" };
        Console.WriteLine(string.Join(", ", SplitIdentifiers(identifiers)));
    }
}
```

