```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

public static class Program
{
    public static int AppendRecord(string filePath, IReadOnlyDictionary<string, string> record)
    {
        ArgumentNullException.ThrowIfNull(filePath);
        ArgumentNullException.ThrowIfNull(record);

        string? directory = Path.GetDirectoryName(filePath);
        if (!string.IsNullOrEmpty(directory)) Directory.CreateDirectory(directory);

        string line = FormatRecord(record);
        if (line.Length > 0) File.AppendAllText(filePath, line + Environment.NewLine, new UTF8Encoding(false));
        return File.Exists(filePath) ? File.ReadAllLines(filePath).Length : 0;
    }

    private static string FormatRecord(IReadOnlyDictionary<string, string> record) =>
        record.Count == 0 ? string.Empty : string.Join("&", record.Select(pair => pair.Key + "=" + EscapeValue(pair.Value)));

    private static string EscapeValue(string value)
    {
        if (string.IsNullOrEmpty(value)) return string.Empty;
        var builder = new StringBuilder(value.Length);
        foreach (char symbol in value)
        {
            switch (symbol)
            {
                case '=': builder.Append("%3D"); break;
                case '&': builder.Append("%26"); break;
                case ' ': builder.Append("%20"); break;
                case '"': builder.Append("%22"); break;
                default: builder.Append(symbol); break;
            }
        }

        return builder.ToString();
    }

    public static void Main()
    {
        var record = new Dictionary<string, string>
        {
            { "name", "John & Smith" },
            { "age", "30" },
        };

        string filePath = Path.Combine(Path.GetTempPath(), "records-demo.txt");
        Console.WriteLine(AppendRecord(filePath, record));
    }
}
