using System;
using System.Collections.Generic;

public static class Program
{
    public static List<T[]> SlidingWindow<T>(IEnumerable<T> source, int windowSize)
    {
        ArgumentNullException.ThrowIfNull(source);
        if (windowSize <= 0) throw new ArgumentException("windowSize must be positive", nameof(windowSize));

        var items = new List<T>(source);
        var windows = new List<T[]>();
        for (int start = 0; start + windowSize <= items.Count; start++)
        {
            var window = new T[windowSize];
            for (int offset = 0; offset < windowSize; offset++) window[offset] = items[start + offset];
            windows.Add(window);
        }

        return windows;
    }

    public static void Main()
    {
        int[] data = { 1, 2, 3, 4, 5, 6, 7 };
        foreach (int[] window in SlidingWindow(data, 3)) Console.WriteLine(string.Join(", ", window));
        Console.WriteLine(SlidingWindow(data, 99).Count);
    }
}
