```csharp
using System;
using System.Text;

public static class Program
{
    private static readonly char[] InvalidChars = { '<', '>', ':', '/', '|', '?', '*', '"' };

    public static string SanitizeFileName(string fileName, int maxLength = 255)
    {
        ArgumentNullException.ThrowIfNull(fileName);
        if (maxLength <= 0) throw new ArgumentOutOfRangeException(nameof(maxLength));
        if (fileName.Length == 0) return "untitled";

        var builder = new StringBuilder(fileName.Length);
        int validCount = 0;
        foreach (char symbol in fileName)
        {
            if (IsInvalid(symbol))
            {
                builder.Append('_');
            }
            else
            {
                builder.Append(symbol);
                validCount++;
            }
        }

        if (validCount == 0) return "untitled";
        string sanitized = builder.ToString();
        return sanitized.Length > maxLength ? sanitized.Substring(0, maxLength) : sanitized;
    }

    private static bool IsInvalid(char symbol) =>
        Array.IndexOf(InvalidChars, symbol) >= 0 || symbol == (char)92 || char.IsControl(symbol);

    public static void Main()
    {
        string[] names = { "my<file>:name.txt", "invalid|file?name", "<<<", "a b" };
        foreach (string name in names) Console.WriteLine(SanitizeFileName(name, 20));
    }
}
```

