using System;
using System.Collections.Generic;

public static class Program
{
    public static Dictionary<TValue, List<TKey>> ReverseMap<TKey, TValue>(IReadOnlyDictionary<TKey, TValue> source)
        where TKey : notnull
        where TValue : notnull
    {
        ArgumentNullException.ThrowIfNull(source);

        var result = new Dictionary<TValue, List<TKey>>();
        foreach (var pair in source)
        {
            if (!result.TryGetValue(pair.Value, out var keys))
            {
                keys = new List<TKey>();
                result[pair.Value] = keys;
            }

            keys.Add(pair.Key);
        }

        return result;
    }

    public static void Main()
