using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static string FillTemplate(string template, IReadOnlyDictionary<string, string> replacements)
    {
        ArgumentNullException.ThrowIfNull(template);
        ArgumentNullException.ThrowIfNull(replacements);

        var builder = new StringBuilder(template.Length);
        int index = 0;
        while (index < template.Length)
        {
            if (template[index] != '$')
            {
                builder.Append(template[index]);
                index++;
                continue;
            }

            if (index + 1 < template.Length && template[index + 1] == '$')
            {
                builder.Append("$$");
                index += 2;
                continue;
            }

            if (index + 1 < template.Length && char.IsLetter(template[index + 1]))
            {
                int end = index + 2;
                while (end < template.Length && char.IsLetterOrDigit(template[end])) end++;
                string name = template.Substring(index + 1, end - index - 1);
                builder.Append(replacements.TryGetValue(name, out var value) ? value : template.Substring(index, end - index));
                index = end;
                continue;
            }

            builder.Append(template[index]);
            index++;
        }

        return builder.ToString();
    }

    public static void Main()
    {
        var replacements = new Dictionary<string, string> { { "name", "Alice" }, { "city", "Oslo" } };
        Console.WriteLine(FillTemplate("Hello, $name from $city and $missing.", replacements));
    }
}
