    public static Statistic CalculateStatistics(IEnumerable<double> numbers)
    {
        if (numbers is null) return new Statistic(0, 0.0, 0.0);
        int count = 0;
        double sum = 0.0;
        double max = double.MinValue;
        foreach (double number in numbers)
        {
