using System;
using System.Collections.Generic;

public static class Program
{
    public static List<T> Interleave<T>(params IEnumerable<T>[] sequences)
    {
        var result = new List<T>();
        if (sequences is null || sequences.Length == 0) return result;

        var enumerators = new List<IEnumerator<T>>();
        foreach (var sequence in sequences)
        {
            if (sequence is null) continue;
            enumerators.Add(sequence.GetEnumerator());
        }

        bool advanced = true;
        while (advanced)
        {
            advanced = false;
            foreach (var enumerator in enumerators)
            {
                if (!enumerator.MoveNext()) continue;
                result.Add(enumerator.Current);
                advanced = true;
            }
        }

        foreach (var enumerator in enumerators) enumerator.Dispose();
        return result;
    }

    public static void Main()
    {
        IEnumerable<int>[] sequences =
        {
            new List<int> { 1, 2, 3 },
            new List<int> { 4, 5, 6 },
            new List<int> { 7, 8 },
            new List<int> { 9 },
        };

        Console.WriteLine(string.Join(", ", Interleave(sequences)));
    }
}
