```csharp
using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static List<string> WrapText(string text, int width)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (width <= 0) throw new ArgumentOutOfRangeException(nameof(width));

        var result = new List<string>();
        if (text.Length == 0) return result;

        foreach (string rawLine in text.Split((char)10))
        {
            string line = rawLine.TrimEnd((char)13);
            if (line.Length == 0)
            {
                result.Add(string.Empty);
                continue;
            }

            var builder = new StringBuilder();
            foreach (string word in line.Split(' ', StringSplitOptions.RemoveEmptyEntries))
            {
                var remaining = word;
                while (remaining.Length > width)
                {
                    if (builder.Length > 0)
                    {
                        result.Add(builder.ToString());
                        builder.Clear();
                    }

                    result.Add(remaining.Substring(0, width));
                    remaining = remaining.Substring(width);
                }

                if (builder.Length == 0)
                {
                    builder.Append(remaining);
                    continue;
                }

                if (builder.Length + 1 + remaining.Length > width)
                {
                    result.Add(builder.ToString());
                    builder.Clear();
                    builder.Append(remaining);
                    continue;
                }

                builder.Append(' ').Append(remaining);
            }

            if (builder.Length > 0) result.Add(builder.ToString());
        }

        return result;
    }

    public static void Main()
    {
        string text = "This is an example of a text that needs to be wrapped." + Environment.NewLine + "Second paragraph stays separate.";
        foreach (string line in WrapText(text, 20)) Console.WriteLine(line);
    }
}
```

