using System;
using System.Collections.Generic;
using System.Linq;

public sealed record ScoreEntry(int Rank, string Name);

public static class Program
{
    public static List<T> StableSortByKey<T, TKey>(IEnumerable<T> source, Func<T, TKey> keySelector)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(keySelector);

        return source.Select((item, index) => (Item: item, Index: index))
            .OrderBy(pair => keySelector(pair.Item), Comparer<TKey>.Default)
            .ThenBy(pair => pair.Index)
            .Select(pair => pair.Item)
            .ToList();
    }

    public static void Main()
    {
        var data = new List<ScoreEntry>
        {
            new ScoreEntry(3, "B"),
            new ScoreEntry(1, "A"),
            new ScoreEntry(2, "C"),
            new ScoreEntry(1, "D"),
        };

        foreach (ScoreEntry entry in StableSortByKey(data, item => item.Rank)) Console.WriteLine(entry);
    }
}
