using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public static class Program
{
    public static string HighlightKeywords(string text, IEnumerable<string> keywords)
    {
        ArgumentNullException.ThrowIfNull(text);
        ArgumentNullException.ThrowIfNull(keywords);

        var distinct = keywords.Where(keyword => !string.IsNullOrEmpty(keyword)).Distinct().ToArray();
        if (distinct.Length == 0) return text;

        var builder = new StringBuilder(text.Length);
        int position = 0;
        while (position < text.Length)
        {
            string? match = null;
            foreach (string keyword in distinct)
            {
                if (string.CompareOrdinal(text, position, keyword, 0, keyword.Length) != 0) continue;
                if (match is null || keyword.Length > match.Length) match = keyword;
            }

            if (match is null)
            {
                builder.Append(text[position]);
                position++;
                continue;
            }

            builder.Append("<highlight>").Append(match).Append("</highlight>");
            position += match.Length;
        }

        return builder.ToString();
    }

    public static void Main()
    {
        var keywords = new List<string> { "apple", "banana" };
        Console.WriteLine(HighlightKeywords("apple, banana, apple and pear.", keywords));
    }
}
