using System;

public static class Program
{
    public static (int, int) CalculatePageBoundaries(int page, int pageSize, int total)
    {
        if (page < 1) throw new ArgumentOutOfRangeException(nameof(page));
        if (pageSize <= 0) throw new ArgumentOutOfRangeException(nameof(pageSize));
        if (total < 0) throw new ArgumentOutOfRangeException(nameof(total));
        if (total == 0) return (0, 0);

        int start = Math.Min((page - 1) * pageSize, total - 1);
        int end = Math.Min(page * pageSize - 1, total - 1);
        return (start, end);
    }

    public static void Main()
    {
        var (start, end) = CalculatePageBoundaries(3, 10, 50);
        Console.WriteLine($"{start}..{end}");
        var (shortStart, shortEnd) = CalculatePageBoundaries(1, 10, 5);
        Console.WriteLine($"{shortStart}..{shortEnd}");
    }
}
