using System;
using System.Collections.Generic;
using System.Linq;

public static class Program
{
    public static (List<T>, List<T>, List<T>) CompareSets<T>(IEnumerable<T> set1, IEnumerable<T> set2)
    {
        var empty = (new List<T>(), new List<T>(), new List<T>());
        if (set1 is null || set2 is null) return empty;

        var left = new HashSet<T>(set1);
        var right = new HashSet<T>(set2);
        var intersection = left.Intersect(right).ToList();
        var leftDifference = left.Except(right).ToList();
        var rightDifference = right.Except(left).ToList();
        return (intersection, leftDifference, rightDifference);
    }

    public static void Main()
    {
        var first = new List<int> { 1, 2, 3, 4, 5 };
        var second = new List<int> { 4, 5, 6, 7, 8 };
        var (intersection, left, right) = CompareSets(first, second);
        Console.WriteLine(string.Join(", ", intersection));
        Console.WriteLine(string.Join(", ", left));
        Console.WriteLine(string.Join(", ", right));
    }
}
