### 📄 `RelativePathCalculator.cs`

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public static class Program
{
    public static string? CalculateRelativePath(string path1, string path2)
    {
        ArgumentNullException.ThrowIfNull(path1);
        ArgumentNullException.ThrowIfNull(path2);
        if (path1.Length == 0 || path2.Length == 0) return null;

        string normalized1 = NormalizePath(path1);
        string normalized2 = NormalizePath(path2);
        if (!IsValidPath(normalized1) || !IsValidPath(normalized2)) return null;

        var from = SplitPath(normalized1);
        var to = SplitPath(normalized2);
        int same = 0;
        while (same < from.Count && same < to.Count && from[same] == to[same]) same++;
        if (same < from.Count) return null;
        if (same == to.Count) return ".";
        return string.Join("/", to.Skip(same));
    }

    private static string NormalizePath(string path) => path.Replace((char)92, '/');

    private static List<string> SplitPath(string path)
    {
        var parts = new List<string>();
        foreach (string part in path.Split('/'))
        {
            if (part.Length > 0) parts.Add(part);
        }

        return parts;
    }

    private static bool IsValidPath(string path)
    {
        foreach (string part in path.Split('/'))
        {
            if (part == "." || part == "..") return false;
        }

        return true;
    }

    public static void Main()
    {
        Console.WriteLine(CalculateRelativePath("a/b/c", "a/b/c/d") ?? "null");
        Console.WriteLine(CalculateRelativePath("a/b/c/d", "a/b/c") ?? "null");
        Console.WriteLine(CalculateRelativePath("a/b/c", "a/b/c") ?? "null");
    }
}
```

