using System;
using System.Collections.Generic;

public static class Program
{
    public static List<string> StripPrefixSuffix(IEnumerable<string> input, string prefix, string suffix)
    {
        ArgumentNullException.ThrowIfNull(prefix);
        ArgumentNullException.ThrowIfNull(suffix);

        var result = new List<string>();
        if (input is null) return result;
        foreach (var item in input)
        {
            string value = item ?? string.Empty;
            bool matchesBoth = value.Length >= prefix.Length + suffix.Length
                && value.StartsWith(prefix, StringComparison.Ordinal)
                && value.EndsWith(suffix, StringComparison.Ordinal);
            if (matchesBoth)
            {
                value = value.Substring(prefix.Length, value.Length - prefix.Length - suffix.Length);
            }

            result.Add(value);
        }

        return result;
    }

    public static void Main()
    {
        var input = new List<string> { "hello", "prefixhello", "prefixhellosuffix", "hellosuffix", "prefixsuffix" };
