using System;
using System.Threading;

public static class RetryWrapper
{
    public static Func<T> Retry<T>(int maxRetries, double retryIntervalSeconds, Func<T> func)
    {
        ArgumentNullException.ThrowIfNull(func);
        if (maxRetries < 1) throw new ArgumentOutOfRangeException(nameof(maxRetries));
        if (retryIntervalSeconds < 0.0) throw new ArgumentOutOfRangeException(nameof(retryIntervalSeconds));

        return () =>
        {
            Exception? lastError = null;
            for (int attempt = 1; attempt <= maxRetries; attempt++)
            {
                try
                {
                    return func();
                }
                catch (Exception error)
                {
                    lastError = error;
                    if (attempt < maxRetries) Thread.Sleep(TimeSpan.FromSeconds(retryIntervalSeconds));
                }
            }

            throw lastError!;
        };
    }
}

public static class Program
{
    public static void Main()
    {
        int attempts = 0;
        Func<int> flaky = () =>
        {
            attempts++;
            if (attempts < 3) throw new InvalidOperationException("transient failure");
            return attempts;
        };

        Console.WriteLine(RetryWrapper.Retry(5, 0.01, flaky)());
    }
}
```

