```csharp
using System;
using System.Diagnostics;
using System.Threading;

public static class Program
{
    public static Func<TResult> RateLimit<TResult>(Func<TResult> originalFunction, double secondsToWait)
    {
        ArgumentNullException.ThrowIfNull(originalFunction);
        var gate = new RateGate(CheckInterval(secondsToWait));
        return () =>
        {
            gate.Wait();
            return originalFunction();
        };
    }

    public static Func<TArg, TResult> RateLimit<TArg, TResult>(Func<TArg, TResult> originalFunction, double secondsToWait)
    {
        ArgumentNullException.ThrowIfNull(originalFunction);
        var gate = new RateGate(CheckInterval(secondsToWait));
        return argument =>
        {
            gate.Wait();
            return originalFunction(argument);
        };
    }

    private static double CheckInterval(double secondsToWait)
    {
        if (secondsToWait < 0.0) throw new ArgumentException("secondsToWait must be non-negative", nameof(secondsToWait));
        return secondsToWait;
    }

    private sealed class RateGate
    {
        private readonly double _interval;
        private readonly Stopwatch _clock = Stopwatch.StartNew();
        private double _lastCall = double.NegativeInfinity;

        public RateGate(double interval) => _interval = interval;

        public void Wait()
        {
            double wait = _lastCall + _interval - _clock.Elapsed.TotalSeconds;
            if (wait > 0.0) Thread.Sleep(TimeSpan.FromSeconds(wait));
            _lastCall = _clock.Elapsed.TotalSeconds;
        }
    }

    public static void Main()
    {
        Func<int, int> doubled = value => value * 2;
        Func<int, int> limited = RateLimit(doubled, 0.05);
        Console.WriteLine(limited(5));
        Console.WriteLine(limited(7));
    }
}
```

