using System;
using System.Collections.Generic;

public static class Program
{
    public static List<T> RotateRight<T>(IReadOnlyList<T> input, int shift)
    {
        ArgumentNullException.ThrowIfNull(input);
        var result = new List<T>(input.Count);
        if (input.Count == 0) return result;

        int effective = shift % input.Count;
        if (effective < 0) effective += input.Count;
        int split = input.Count - effective;
        for (int i = split; i < input.Count; i++) result.Add(input[i]);
        for (int i = 0; i < split; i++) result.Add(input[i]);
        return result;
    }

    public static void Main()
    {
        var numbers = new List<int> { 1, 2, 3, 4, 5 };
        Console.WriteLine(string.Join(", ", RotateRight(numbers, 1)));
        Console.WriteLine(string.Join(", ", RotateRight(numbers, 2)));
        Console.WriteLine(string.Join(", ", RotateRight(numbers, 5)));
