using System;
using System.Collections.Generic;

public static class TableRenderer
{
    public static string RenderTable(IEnumerable<string[]> rows)
    {
        if (rows is null) return string.Empty;
        var materialized = new List<string[]>();
        foreach (var row in rows)
        {
            if (row is not null) materialized.Add(row);
        }

        if (materialized.Count == 0) return string.Empty;

        int columns = 0;
        foreach (var row in materialized) columns = Math.Max(columns, row.Length);
        var widths = new int[columns];
        foreach (var row in materialized)
        {
            for (int i = 0; i < row.Length; i++) widths[i] = Math.Max(widths[i], row[i].Length);
        }

        var lines = new List<string>(materialized.Count);
        foreach (var row in materialized)
        {
            var cells = new string[columns];
            for (int i = 0; i < columns; i++)
            {
                string cell = i < row.Length ? row[i] : string.Empty;
                cells[i] = cell.PadRight(widths[i]);
            }

            lines.Add(string.Join(" ", cells).TrimEnd());
        }

        return string.Join(Environment.NewLine, lines);
    }
}

