using System;
using System.Collections.Generic;

public static class Program
{
    public static Func<T, TResult> Memoize<T, TResult>(Func<T, TResult> func) where T : notnull
    {
        ArgumentNullException.ThrowIfNull(func);
        var cache = new Dictionary<T, TResult>();
        return argument =>
        {
            if (cache.TryGetValue(argument, out TResult cached)) return cached;
            TResult computed = func(argument);
            cache[argument] = computed;
            return computed;
        };
    }

    public static void Main()
    {
        var calls = 0;
        Func<int, int> slow = value =>
        {
            calls++;
            return value * 2;
        };

        Func<int, int> memoized = Memoize(slow);
        Console.WriteLine(memoized(5));
        Console.WriteLine(memoized(5));
        Console.WriteLine(memoized(10));
        Console.WriteLine(calls);
    }
}
```

