using System;

public static class Program
{
    public static string MaskEmail(string email, int keepDigits = 3)
    {
        if (keepDigits < 0) throw new ArgumentOutOfRangeException(nameof(keepDigits), "keepDigits must not be negative");
        if (string.IsNullOrEmpty(email)) return email;

        int at = email.IndexOf('@');
        if (at <= 0 || at == email.Length - 1) return email;
        string username = email.Substring(0, at);
        string domain = email.Substring(at + 1);
        if (username.Length <= keepDigits) return email;
        return username.Substring(0, keepDigits) + new string('*', username.Length - keepDigits) + "@" + domain;
    }

    public static void Main()
    {
        string[] samples = { "test@example.com", "user123@example.com", "invalid-email", "a@example.com" };
        foreach (string sample in samples) Console.WriteLine(MaskEmail(sample, 3));
    }
}
