using System;
using System.Collections.Generic;
using System.Text;

public static class Program
{
    public static string NormalizeWhitespace(IEnumerable<string> textLines)
    {
        if (textLines is null) return string.Empty;

        var builder = new StringBuilder();
        bool pendingSpace = false;
        foreach (var line in textLines)
        {
            if (string.IsNullOrEmpty(line))
            {
                if (builder.Length > 0) pendingSpace = true;
                continue;
            }

            if (builder.Length > 0) pendingSpace = true;

            foreach (char symbol in line)
            {
                if (char.IsWhiteSpace(symbol))
                {
                    if (builder.Length > 0) pendingSpace = true;
                    continue;
                }

                if (pendingSpace)
                {
                    builder.Append(' ');
                    pendingSpace = false;
                }

                builder.Append(symbol);
            }
        }

        return builder.ToString();
    }

    public static void Main()
    {
        var lines = new List<string> { "  Hello   world  ", "   This is a test   ", "   " };
        Console.WriteLine(NormalizeWhitespace(lines));
        Console.WriteLine(NormalizeWhitespace(new List<string> { "   ", "  " }) == string.Empty);
    }
}
