using System;
using System.Collections.Generic;

public static class IdentifierValidator
{
    private static readonly HashSet<string> Reserved = new HashSet<string>(StringComparer.Ordinal)
    {
        "int", "string", "bool", "char", "double", "float", "void", "class", "enum", "static",
    };

    public static List<string> ValidateIdentifiers(IEnumerable<string> identifiers)
    {
        var invalid = new List<string>();
        if (identifiers is null) return invalid;

        foreach (var identifier in identifiers)
        {
            if (!IsValid(identifier)) invalid.Add(identifier ?? string.Empty);
        }

        return invalid;
    }

    private static bool IsValid(string? identifier)
    {
        if (string.IsNullOrEmpty(identifier)) return false;
        if (char.IsDigit(identifier[0])) return false;
        foreach (char symbol in identifier)
        {
            if (!char.IsLetterOrDigit(symbol) && symbol != '_') return false;
        }

        return !Reserved.Contains(identifier);
    }
}

public static class Program
{
    public static void Main()
    {
        var identifiers = new List<string> { "abc123", "123abc", "abc_123", "int", "a-b" };
        foreach (string name in IdentifierValidator.ValidateIdentifiers(identifiers)) Console.WriteLine(name);
    }
}
```

