using System;
using System.Collections.Generic;

public static class Program
{
    public static List<(T Item, int Count)> RunLengthEncode<T>(IEnumerable<T> input)
    {
        var result = new List<(T Item, int Count)>();
        if (input is null) return result;

        using var enumerator = input.GetEnumerator();
        if (!enumerator.MoveNext()) return result;
        T current = enumerator.Current;
        int count = 1;
        while (enumerator.MoveNext())
        {
            if (EqualityComparer<T>.Default.Equals(enumerator.Current, current))
            {
                count++;
                continue;
            }

            result.Add((current, count));
            current = enumerator.Current;
            count = 1;
        }

        result.Add((current, count));
        return result;
    }

    public static void Main()
    {
        var data = new List<int> { 1, 1, 2, 2, 2, 3, 3, 4 };
        foreach (var run in RunLengthEncode(data)) Console.WriteLine($"{run.Item}:{run.Count}");
        Console.WriteLine(RunLengthEncode(new List<int>()).Count);
    }
}
