```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public static class Program
{
    public static int LevenshteinDistance(IEnumerable<char> source, IEnumerable<char> target)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(target);

        char[] left = source as char[] ?? source.ToArray();
        char[] right = target as char[] ?? target.ToArray();
        var previous = new int[right.Length + 1];
        var current = new int[right.Length + 1];
        for (int j = 0; j <= right.Length; j++) previous[j] = j;

        for (int i = 1; i <= left.Length; i++)
        {
            current[0] = i;
            for (int j = 1; j <= right.Length; j++)
            {
                int substitute = previous[j - 1] + (left[i - 1] == right[j - 1] ? 0 : 1);
                current[j] = Math.Min(substitute, Math.Min(previous[j] + 1, current[j - 1] + 1));
            }

            (previous, current) = (current, previous);
        }

        return previous[right.Length];
    }

    public static void Main()
    {
        Console.WriteLine(LevenshteinDistance("kitten", "sitting"));
        Console.WriteLine(LevenshteinDistance("", ""));
        Console.WriteLine(LevenshteinDistance("abc", ""));
    }
}
```

