using System;
using System.Collections.Generic;

public static class Program
{
    public static bool CheckBrackets(IEnumerable<char> characters, IReadOnlyDictionary<char, char> bracketMap)
    {
        ArgumentNullException.ThrowIfNull(characters);
        ArgumentNullException.ThrowIfNull(bracketMap);

        var closing = new Dictionary<char, char>();
        foreach (var pair in bracketMap) closing[pair.Value] = pair.Key;

        var stack = new Stack<char>();
        foreach (char symbol in characters)
        {
            if (closing.TryGetValue(symbol, out char opener))
            {
                if (stack.Count == 0) return false;
                if (stack.Pop() != opener) return false;
                continue;
            }

            if (bracketMap.ContainsKey(symbol)) stack.Push(symbol);
        }

        return stack.Count == 0;
    }

    public static void Main()
    {
        var bracketMap = new Dictionary<char, char>
        {
            { '(', ')' },
            { '[', ']' },
            { '{', '}' },
        };

        Console.WriteLine(CheckBrackets("{[()]}", bracketMap));
        Console.WriteLine(CheckBrackets("(]", bracketMap));
        Console.WriteLine(CheckBrackets("((", bracketMap));
    }
}
