using System;
using System.Collections.Generic;

public static class Program
{
    private static readonly IReadOnlyDictionary<string, int> DefaultUnits =
        new Dictionary<string, int> { { "h", 3600 }, { "m", 60 }, { "s", 1 } };

    public static int ParseDuration(string input, IReadOnlyDictionary<string, int>? units = null)
    {
        units ??= DefaultUnits;
        if (string.IsNullOrWhiteSpace(input)) return 0;

        string text = input.Trim().ToLowerInvariant();
        int total = 0;
        int index = 0;
        while (index < text.Length)
        {
            int start = index;
            while (index < text.Length && char.IsDigit(text[index])) index++;
            if (index == start) return 0;
            if (!int.TryParse(text.Substring(start, index - start), out int value)) return 0;

            start = index;
            while (index < text.Length && char.IsLetter(text[index])) index++;
            if (index == start) return 0;
            string unit = text.Substring(start, index - start);
            if (!units.TryGetValue(unit, out int factor)) return 0;
            total += value * factor;
        }

        return total;
    }

    public static void Main()
    {
        var units = new Dictionary<string, int>
        {
            { "h", 3600 },
            { "m", 60 },
            { "s", 1 },
        };

        Console.WriteLine(ParseDuration("1h30m", units));
        Console.WriteLine(ParseDuration("2h45m30s", units));
        Console.WriteLine(ParseDuration("10s", units));
        Console.WriteLine(ParseDuration("abc", units));
    }
}
