using System;
using System.Collections.Generic;

public static class Program
{
    public static List<T[]> TransposeMatrix<T>(IEnumerable<IEnumerable<T>> matrix)
    {
        var rows = new List<List<T>>();
        if (matrix is not null)
        {
            foreach (var row in matrix)
            {
                rows.Add(row is null ? new List<T>() : new List<T>(row));
            }
        }

        var result = new List<T[]>();
        if (rows.Count == 0) return result;

        int width = int.MaxValue;
        foreach (var row in rows) width = Math.Min(width, row.Count);
        for (int column = 0; column < width; column++)
        {
            var values = new T[rows.Count];
            for (int rowIndex = 0; rowIndex < rows.Count; rowIndex++) values[rowIndex] = rows[rowIndex][column];
            result.Add(values);
        }

        return result;
    }

    public static void Main()
    {
        var matrix = new List<List<int>>
        {
            new List<int> { 1, 2, 3 },
            new List<int> { 4, 5 },
            new List<int> { 7, 8, 9 },
        };

        foreach (int[] column in TransposeMatrix(matrix)) Console.WriteLine(string.Join(", ", column));
    }
}
