using System;
using System.Collections.Generic;

public static class QueryStringParser
{
    public static Dictionary<string, List<string>> ParseQueryString(
        string queryString,
        IReadOnlyDictionary<string, string>? defaultValues = null)
    {
        ArgumentNullException.ThrowIfNull(queryString);

        var result = new Dictionary<string, List<string>>();
        var body = queryString.TrimStart('?');

        foreach (var pair in body.Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var separator = pair.IndexOf('=');
            if (separator <= 0)
            {
                continue;
            }

            var key = pair[..separator];
            var value = pair[(separator + 1)..];
            if (result.TryGetValue(key, out var existing))
            {
                existing.Add(value);
            }
            else
            {
                result[key] = new List<string> { value };
            }
        }

        if (defaultValues is not null)
        {
            foreach (var entry in defaultValues)
            {
                if (!result.ContainsKey(entry.Key))
                {
                    result[entry.Key] = new List<string> { entry.Value };
                }
            }
        }

        return result;
    }

    public static void Main()
    {
        var defaults = new Dictionary<string, string> { { "country", "unknown" } };
        var parsed = ParseQueryString("?name=alice&name=bob&country=usa", defaults);
        foreach (var entry in parsed)
        {
            Console.WriteLine($"{entry.Key}: {string.Join(", ", entry.Value)}");
        }
    }
}
