```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

public static class CsvSupport
{
    public static List<Dictionary<string, string>> ReadCsvToDictionaryList(string filePath, Encoding? encoding = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(filePath);

        var rows = new List<Dictionary<string, string>>();
        if (!File.Exists(filePath))
        {
            return rows;
        }

        using var reader = new StreamReader(filePath, encoding ?? Encoding.UTF8);
        var header = reader.ReadLine();
        if (string.IsNullOrWhiteSpace(header))
        {
            return rows;
        }

        var headers = header.Split(',');
        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0)
            {
                continue;
            }

            var values = SplitCsvLine(line);
            var row = new Dictionary<string, string>();
            for (var index = 0; index < headers.Length; index++)
            {
                row[headers[index]] = index < values.Length ? values[index] : string.Empty;
            }

            rows.Add(row);
        }

        return rows;
    }

    private static string[] SplitCsvLine(string line)
    {
        var fields = new List<string>();
        var current = new StringBuilder();
        var quoted = false;
        for (var index = 0; index < line.Length; index++)
        {
            var symbol = line[index];
            if (quoted)
            {
                if (symbol == '"')
                {
                    if (index + 1 < line.Length && line[index + 1] == '"')
                    {
                        current.Append('"');
                        index++;
                    }
                    else
                    {
                        quoted = false;
                    }
                }
                else
                {
                    current.Append(symbol);
                }
            }
            else if (symbol == '"')
            {
                quoted = true;
            }
            else if (symbol == ',')
            {
                fields.Add(current.ToString());
                current.Clear();
            }
            else
            {
                current.Append(symbol);
            }
        }

        fields.Add(current.ToString());
        return fields.ToArray();
    }
}

public static class Program
{
    public static void Main()
    {
