using System;
using System.Text.RegularExpressions;

public static class SizeParser
{
    private static readonly Regex SizePattern = new("^ *([0-9]+) *[xX] *([0-9]+) *$", RegexOptions.Compiled);

    public static (int Width, int Height) ParseSize(string input)
    {
        ArgumentNullException.ThrowIfNull(input);

        var match = SizePattern.Match(input);
        if (!match.Success)
        {
            return (0, 0);
        }

        if (!int.TryParse(match.Groups[1].Value, out var width) || !int.TryParse(match.Groups[2].Value, out var height))
        {
            return (0, 0);
        }

        return (width, height);
    }
}

public static class Program
{
