    {
        string[] cases = { "800x600", "800 x 600", "1280X720", "abcx100", "100x200 300" };
        foreach (var item in cases)
        {
            var size = SizeParser.ParseSize(item);
            Console.WriteLine($"{item} -> ({size.Width}, {size.Height})");
        }
    }
}
