using System;
using System.Collections.Generic;

public sealed class LazyValueCache<TKey, TValue> where TKey : notnull
{
    private readonly IReadOnlyDictionary<TKey, Func<TValue>> _factories;

    private readonly Dictionary<TKey, TValue> _cache = new();

    public LazyValueCache(IReadOnlyDictionary<TKey, Func<TValue>> factories)
    {
        ArgumentNullException.ThrowIfNull(factories);
        _factories = factories;
    }

    public TValue this[TKey key]
    {
        get
        {
            if (_cache.TryGetValue(key, out var cached))
            {
                return cached;
            }

            if (!_factories.TryGetValue(key, out var factory))
            {
                throw new KeyNotFoundException($"No factory registered for key '{key}'.");
            }

            var value = factory();
            _cache[key] = value;
            return value;
        }
    }
}

public static class Program
{
    public static void Main()
    {
        var factories = new Dictionary<string, Func<string>>
        {
            ["A"] = () => "value a",
            ["B"] = () => "value b"
        };

        var cache = new LazyValueCache<string, string>(factories);
        Console.WriteLine(cache["A"]);
        Console.WriteLine(cache["A"]);
        try
        {
            Console.WriteLine(cache["Z"]);
        }
        catch (KeyNotFoundException error)
        {
            Console.WriteLine(error.Message);
        }
    }
}
```

