using System;
using System.Collections.Generic;

public static class ConfigMerger
{
    public static Dictionary<string, object> MergeConfig(
        IReadOnlyDictionary<string, object> config1,
        IReadOnlyDictionary<string, object> config2)
    {
        ArgumentNullException.ThrowIfNull(config1);
        ArgumentNullException.ThrowIfNull(config2);

        var result = new Dictionary<string, object>();
        foreach (var entry in config1)
        {
            result[entry.Key] = entry.Value;
        }

        foreach (var entry in config2)
        {
            if (result.TryGetValue(entry.Key, out var existing)
                && existing is IReadOnlyDictionary<string, object> left
                && entry.Value is IReadOnlyDictionary<string, object> right)
            {
                result[entry.Key] = MergeConfig(left, right);
            }
            else
            {
                result[entry.Key] = entry.Value;
            }
        }

        return result;
    }
}

public static class Program
{
    public static void Main()
    {
        var first = new Dictionary<string, object>
        {
            ["name"] = "alice",
            ["settings"] = new Dictionary<string, object> { ["theme"] = "dark", ["sms"] = false }
        };
        var second = new Dictionary<string, object>
        {
            ["name"] = "bob",
            ["settings"] = new Dictionary<string, object> { ["theme"] = "light", ["sms"] = true }
        };

        var merged = ConfigMerger.MergeConfig(first, second);
        PrintDictionary(merged, string.Empty);
    }

    private static void PrintDictionary(IReadOnlyDictionary<string, object> source, string indent)
    {
        foreach (var entry in source)
        {
            if (entry.Value is IReadOnlyDictionary<string, object> nested)
            {
                Console.WriteLine($"{indent}{entry.Key}:");
                PrintDictionary(nested, indent + "  ");
            }
            else
            {
                Console.WriteLine($"{indent}{entry.Key}={entry.Value}");
            }
        }
    }
}
```

