public static class DifferenceCalculator
{
    public static List<double> CalculateAdjacentDifferences(IEnumerable<double> numbers)
    {
        ArgumentNullException.ThrowIfNull(numbers);

        var differences = new List<double>();
        using var iterator = numbers.GetEnumerator();
        if (!iterator.MoveNext())
        {
            return differences;
        }

        var previous = iterator.Current;
        while (iterator.MoveNext())
        {
            differences.Add(iterator.Current - previous);
            previous = iterator.Current;
        }

        return differences;
    }
}

