using System;
using System.Collections.Generic;

public static class IndentReformatter
{
    public static List<string> IndentLines(IEnumerable<string> lines, int indentStep)
    {
        ArgumentNullException.ThrowIfNull(lines);
        if (indentStep <= 0)
        {
            throw new ArgumentException("Indent step must be positive.", nameof(indentStep));
        }

        var reformatted = new List<string>();
        foreach (var line in lines)
        {
            if (string.IsNullOrWhiteSpace(line))
            {
                reformatted.Add(string.Empty);
                continue;
            }

            var content = line.TrimStart();
            var depth = (line.Length - content.Length) / indentStep;
            reformatted.Add(new string(' ', depth * indentStep) + content);
        }

        return reformatted;
    }
}

public static class Program
{
    public static void Main()
    {
        var lines = new List<string>
        {
            "void Run()",
            "  if (ready)",
            "      Console.WriteLine(1);",
            string.Empty
        };

        foreach (var line in IndentReformatter.IndentLines(lines, 4))
        {
            Console.WriteLine($"[{line}]");
        }
    }
}
