using System.Linq;
using System.Security.Cryptography;
using System.Text;

public static class CacheKeyBuilder
{
    public static string ComputeStableCacheKey(IReadOnlyDictionary<string, string> input)
    {
        ArgumentNullException.ThrowIfNull(input);

        var payload = string.Join(
            string.Empty,
            input.OrderBy(entry => entry.Key, StringComparer.Ordinal)
                .Select(entry => $"{entry.Key}={entry.Value};"));
