public static class CommandLineArgsBuilder
{
    private const string SpecialCharacters = " \t'<>|&\u0022";

    private const char Quote = '\u0022';

    public static string BuildCommandLine(IEnumerable<string> args)
    {
        ArgumentNullException.ThrowIfNull(args);

        var parts = new List<string>();
        foreach (var argument in args)
        {
            var needsQuoting = argument.AsSpan().IndexOfAny(SpecialCharacters) >= 0;
            parts.Add(needsQuoting ? Quote + argument + Quote : argument);
        }

        return string.Join(" ", parts);
    }
}

