using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;

public sealed class FileBlockReader : IEnumerable<byte[]>
{
    private readonly string _filePath;

    private readonly int _blockSize;

    public FileBlockReader(string filePath, int blockSize)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(filePath);
        if (blockSize <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(blockSize), "Block size must be positive.");
        }

        _filePath = filePath;
        _blockSize = blockSize;
    }

    public IEnumerator<byte[]> GetEnumerator()
    {
        if (!File.Exists(_filePath))
        {
            throw new FileNotFoundException("File not found.", _filePath);
        }

        using var stream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.Read);
        var buffer = new byte[_blockSize];
        int read;
        while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
        {
            var block = new byte[read];
            Array.Copy(buffer, block, read);
            yield return block;
        }
    }

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}

public static class Program
{
    public static void Main()
    {
        var path = Path.Combine(Path.GetTempPath(), "blocks.bin");
        File.WriteAllBytes(path, new byte[2500]);
        var reader = new FileBlockReader(path, 1024);
        foreach (var block in reader)
        {
            Console.WriteLine(block.Length);
        }
    }
}
```

