    public static List<string> ListZipEntries(string zipFilePath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(zipFilePath);

        var entries = new List<string>();
        if (!File.Exists(zipFilePath))
        {
            return entries;
        }

        try
