using System;
using System.Collections.Generic;

public static class PathValueGetter
{
    public static object? GetValue(
        IReadOnlyDictionary<string, object?> source,
        string path,
        object? defaultValue = null)
    {
        ArgumentNullException.ThrowIfNull(source);

        if (string.IsNullOrWhiteSpace(path))
        {
            return defaultValue;
        }

        object? current = source;
        foreach (var segment in path.Split('.', StringSplitOptions.RemoveEmptyEntries))
        {
            if (current is not IReadOnlyDictionary<string, object?> layer
                || !layer.TryGetValue(segment, out current))
            {
                return defaultValue;
            }
        }

        return current;
    }
}

public static class Program
{
    public static void Main()
    {
        var data = new Dictionary<string, object?>
        {
            ["a"] = new Dictionary<string, object?> { ["b"] = new Dictionary<string, object?> { ["c"] = 42 } },
            ["x"] = 100
        };

        Console.WriteLine(PathValueGetter.GetValue(data, "a.b.c", 0));
        Console.WriteLine(PathValueGetter.GetValue(data, "a.b.d", "missing"));
        Console.WriteLine(PathValueGetter.GetValue(data, "x", "missing"));
