using System;
using System.Collections.Generic;
using System.Linq;

public static class PrefixFinder
{
    public static string LongestCommonPrefix(IEnumerable<string> strings)
    {
        ArgumentNullException.ThrowIfNull(strings);

        var items = strings.ToList();
        if (items.Count == 0)
        {
            return string.Empty;
        }

        var prefix = items[0];
        foreach (var item in items)
        {
            while (!item.StartsWith(prefix, StringComparison.Ordinal))
            {
                prefix = prefix[..^1];
                if (prefix.Length == 0)
                {
                    return string.Empty;
                }
            }
        }

        return prefix;
    }
}

public static class Program
{
