    {
        Console.WriteLine(PrefixFinder.LongestCommonPrefix(new List<string> { "apple", "app", "apricot" }));
        Console.WriteLine(PrefixFinder.LongestCommonPrefix(new List<string> { "a", "" }).Length);
        Console.WriteLine(PrefixFinder.LongestCommonPrefix(new List<string> { "a", "b" }).Length);
