```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public static class RowSorter
{
    public static List<Dictionary<string, double>> SortByFields(
        IEnumerable<IReadOnlyDictionary<string, double>> data,
        IEnumerable<string> sortFields)
    {
        ArgumentNullException.ThrowIfNull(data);
        ArgumentNullException.ThrowIfNull(sortFields);

        var fields = sortFields.ToList();
        var rows = data.ToList();
        if (rows.Count == 0)
        {
            return new List<Dictionary<string, double>>();
        }

        if (fields.Count == 0)
        {
            return rows.Select(row => new Dictionary<string, double>(row)).ToList();
        }

        var ordered = rows.OrderBy(row => Lookup(row, fields[0]));
        for (var index = 1; index < fields.Count; index++)
        {
            var field = fields[index];
            ordered = ordered.ThenBy(row => Lookup(row, field));
        }

        return ordered.Select(row => new Dictionary<string, double>(row)).ToList();
    }

    private static double Lookup(IReadOnlyDictionary<string, double> row, string field)
    {
        return row.TryGetValue(field, out var value) ? value : 0.0;
    }
}

public static class Program
{
    public static void Main()
    {
        var rows = new List<IReadOnlyDictionary<string, double>>
        {
            new Dictionary<string, double> { ["score"] = 90, ["age"] = 30 },
            new Dictionary<string, double> { ["score"] = 90, ["age"] = 25 },
            new Dictionary<string, double> { ["age"] = 40 }
        };

        foreach (var row in RowSorter.SortByFields(rows, new[] { "score", "age" }))
        {
            Console.WriteLine(string.Join(", ", row.Select(entry => $"{entry.Key}={entry.Value}")));
        }
    }
}
