using System;
using System.Collections.Generic;

public sealed class Batcher<T>
{
    private readonly IEnumerable<T> _source;

    private readonly int _batchSize;

    public Batcher(IEnumerable<T> source, int batchSize)
    {
        ArgumentNullException.ThrowIfNull(source);
        if (batchSize <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(batchSize), "Batch size must be greater than zero.");
        }

        _source = source;
        _batchSize = batchSize;
    }

    public IEnumerable<List<T>> Batch()
    {
        var current = new List<T>(_batchSize);
        foreach (var item in _source)
        {
            current.Add(item);
            if (current.Count == _batchSize)
            {
                yield return current;
                current = new List<T>(_batchSize);
            }
        }

        if (current.Count > 0)
        {
            yield return current;
        }
    }
}

public static class Program
{
    public static void Main()
    {
        var batcher = new Batcher<int>(new List<int> { 1, 2, 3, 4, 5, 6, 7 }, 3);
        foreach (var batch in batcher.Batch())
        {
            Console.WriteLine(string.Join(", ", batch));
        }
    }
}
