import kotlin.math.sqrt

class KNNClassifier(private val k: Int = 3) {
    private var trainingData: List<List<Double>>? = null
    private var labels: List<Int>? = null

    init {
        require(k > 0) { "k must be positive" }
    }

    fun fit(samples: List<List<Double>>, targets: List<Int>): KNNClassifier {
        require(samples.isNotEmpty()) { "training data must not be empty" }
        require(samples.size == targets.size) { "samples and targets must have the same size" }
        val width = samples.first().size
        require(width > 0 && samples.all { it.size == width }) { "all samples must share the same dimension" }
        trainingData = samples.map { it.toList() }
        labels = targets.toList()
        return this
    }

    fun predict(queries: List<List<Double>>): List<Int> {
        val data = requireNotNull(trainingData) { "fit must be called before predict" }
        val targets = requireNotNull(labels) { "fit must be called before predict" }
        val limit = minOf(k, data.size)
        return queries.map { query ->
            val nearest = data.indices.sortedBy { index -> euclideanDistance(query, data[index]) }.take(limit)
            nearest.map { index -> targets[index] }
                .groupingBy { label -> label }
                .eachCount()
                .maxByOrNull { entry -> entry.value }
                ?.key ?: targets.first()
        }
    }

    private fun euclideanDistance(left: List<Double>, right: List<Double>): Double {
        var sum = 0.0
        for (index in left.indices) {
            val diff = left[index] - right[index]
            sum += diff * diff
        }
        return sqrt(sum)
    }
}

fun main() {
    val samples = listOf(listOf(0.0, 0.0), listOf(0.0, 1.0), listOf(5.0, 5.0), listOf(6.0, 5.0))
    val targets = listOf(0, 0, 1, 1)
    val classifier = KNNClassifier(3).fit(samples, targets)
    println(classifier.predict(listOf(listOf(0.5, 0.5), listOf(5.5, 5.0))))
}
