以下是一个使用 Kotlin (JVM 17) 编写的 KMeans 聚类类，支持 `maxIter`、`tol` 和 `randomState` 参数，具备空簇时随机重选中心的功能，并提供 `predict` 方法用于对数据进行预测。代码只包含一个 `.kt` 文件，使用标准库实现，不含额外依赖。

```kotlin
import kotlin.math.sqrt
import kotlin.random.Random

class KMeans(
    private val k: Int,
    private val maxIter: Int = 100,
    private val tol: Double = 1e-4,
    private val randomState: Int = 42
) {
    private var centroids: List<List<Double>>? = null
    private var random: Random = Random(randomState)

    init {
        require(k > 0) { "k must be at least 1" }
        require(maxIter > 0) { "maxIter must be positive" }
        require(tol > 0.0) { "tol must be positive" }
    }

    fun fit(samples: List<List<Double>>): KMeans {
        val width = columnWidth(samples)
        require(samples.size >= k) { "number of samples must be at least k" }
        random = Random(randomState)
        var current = initializeCentroids(samples)
        var iteration = 0
        while (iteration < maxIter) {
            val assigned = assignPoints(samples, current, width)
            val updated = computeCentroids(samples, assigned, current, width)
            val converged = isConverged(current, updated)
            current = updated
            if (converged) break
            iteration++
        }
        centroids = current
        return this
    }

    fun predict(samples: List<List<Double>>): List<Int> {
        val centers = requireNotNull(centroids) { "fit must be called before predict" }
        return assignPoints(samples, centers, columnWidth(samples))
    }

    private fun columnWidth(samples: List<List<Double>>): Int {
        require(samples.isNotEmpty()) { "samples must not be empty" }
        val width = samples.first().size
        require(width > 0 && samples.all { it.size == width }) { "all samples must share the same dimension" }
        return width
    }

    private fun initializeCentroids(samples: List<List<Double>>): List<List<Double>> {
        return samples.indices.shuffled(random).take(k).map { index -> samples[index].toList() }
    }

    private fun assignPoints(samples: List<List<Double>>, centers: List<List<Double>>, width: Int): List<Int> {
        return samples.map { point ->
            var best = 0
            var bestDistance = Double.MAX_VALUE
            for (index in centers.indices) {
                val distance = euclideanDistance(point, centers[index], width)
                if (distance < bestDistance) {
                    bestDistance = distance
                    best = index
                }
            }
            best
        }
    }

    private fun computeCentroids(
        samples: List<List<Double>>,
        assigned: List<Int>,
        previous: List<List<Double>>,
        width: Int
    ): List<List<Double>> {
        return (0 until k).map { cluster ->
            val members = samples.indices.filter { index -> assigned[index] == cluster }
            if (members.isEmpty()) {
                previous[random.nextInt(previous.size)].toList()
            } else {
                (0 until width).map { axis -> members.sumOf { index -> samples[index][axis] } / members.size }
            }
        }
    }

    private fun isConverged(previous: List<List<Double>>, current: List<List<Double>>): Boolean {
        if (previous.size != current.size) return false
        return previous.indices.all { index ->
            euclideanDistance(previous[index], current[index], previous[index].size) <= tol
        }
    }

    private fun euclideanDistance(left: List<Double>, right: List<Double>, width: Int): Double {
        var sum = 0.0
        for (axis in 0 until width) {
            val diff = left[axis] - right[axis]
            sum += diff * diff
        }
        return sqrt(sum)
    }
}

fun main() {
    val samples = listOf(
        listOf(1.0, 2.0),
        listOf(1.5, 1.8),
        listOf(5.0, 8.0),
        listOf(8.0, 8.0),
        listOf(9.0, 11.0)
    )
    val model = KMeans(2, maxIter = 100, tol = 1e-4, randomState = 42).fit(samples)
    println(model.predict(samples))
}
```

