### ✅ Fuzzy C-Means 聚类类（单文件）

```kotlin
import kotlin.math.pow
import kotlin.math.sqrt
import kotlin.random.Random

class FuzzyCMeans(
    private val m: Double,
    private val maxIter: Int = 100,
    private val tol: Double = 1e-4,
    private val randomState: Long = 42L
) {
    private var centroids: List<List<Double>> = emptyList()
    private var membership: List<List<Double>> = emptyList()
    private var labels: List<Int> = emptyList()

    init {
        require(m > 1.0) { "m must be greater than 1" }
        require(maxIter > 0) { "maxIter must be positive" }
        require(tol > 0.0) { "tol must be positive" }
    }

    fun fit(samples: List<List<Double>>, clusterCount: Int): FuzzyCMeans {
        require(clusterCount > 0) { "clusterCount must be positive" }
        require(samples.size >= clusterCount) { "number of samples must be at least clusterCount" }
        val width = samples.first().size
        require(width > 0 && samples.all { it.size == width }) { "all samples must share the same dimension" }
        centroids = samples.shuffled(Random(randomState)).take(clusterCount).map { it.toList() }
        var current = membership
        var iteration = 0
        while (iteration < maxIter) {
            current = updateMembership(samples, clusterCount)
            val updated = updateCentroids(samples, current, clusterCount, width)
            val shift = maxShift(centroids, updated)
            centroids = updated
            if (shift <= tol) break
            iteration++
        }
        membership = current
        labels = current.map { row -> row.indices.maxByOrNull { cluster -> row[cluster] } ?: 0 }
        return this
    }

    fun getCentroids(): List<List<Double>> = centroids

    fun getMembership(): List<List<Double>> = membership

    fun getLabels(): List<Int> = labels

    private fun updateMembership(samples: List<List<Double>>, clusterCount: Int): List<List<Double>> {
        return samples.map { point ->
            val weights = (0 until clusterCount).map { cluster ->
                1.0 / (distance(point, centroids[cluster]) + EPSILON).pow(2.0 / (m - 1.0))
            }
            val total = weights.sum()
            weights.map { weight -> weight / total }
        }
    }

    private fun updateCentroids(
        samples: List<List<Double>>,
        rows: List<List<Double>>,
        clusterCount: Int,
        width: Int
    ): List<List<Double>> {
        return (0 until clusterCount).map { cluster ->
            val powered = rows.map { row -> row[cluster].pow(m) }
            val total = powered.sum()
            (0 until width).map { axis ->
                if (total <= 0.0) {
                    samples.first()[axis]
                } else {
                    samples.indices.sumOf { index -> powered[index] * samples[index][axis] } / total
                }
            }
        }
    }

    private fun maxShift(previous: List<List<Double>>, current: List<List<Double>>): Double {
        if (previous.size != current.size) return Double.MAX_VALUE
        return previous.indices.maxOf { index -> distance(previous[index], current[index]) }
    }

    private fun distance(left: List<Double>, right: List<Double>): Double {
        var sum = 0.0
        for (axis in left.indices) {
            val diff = left[axis] - right[axis]
            sum += diff * diff
        }
        return sqrt(sum)
    }

    private companion object {
        private const val EPSILON = 1e-12
    }
}

fun main() {
    val samples = listOf(listOf(0.0, 0.0), listOf(0.2, 0.1), listOf(5.0, 5.0), listOf(5.2, 4.9))
    val model = FuzzyCMeans(2.0, maxIter = 50, tol = 1e-4, randomState = 42L).fit(samples, 2)
    println(model.getLabels())
    println(model.getMembership().size)
}
```

