data class Person(val id: Int, val name: String)

fun <T, K> deduplicate(items: Iterable<T>, keySelector: (T) -> K): List<T> {
    val seen = HashSet<K>()
    val result = ArrayList<T>()
    for (item in items) {
        if (seen.add(keySelector(item))) {
            result.add(item)
        }
    }
    return result
}

fun main() {
    println(deduplicate(listOf(1, 2, 1, 3, 2)) { value -> value })
    val people = listOf(Person(1, "Ann"), Person(1, "Ann"), Person(2, "Bob"))
    println(deduplicate(people) { person -> person.id }.size)
}
