private fun isFullWidthCodePoint(code: Int): Boolean {
    return code in 0x1100..0x115F ||
        code in 0x2E80..0xA4CF ||
        code in 0xAC00..0xD7A3 ||
        code in 0xF900..0xFAFF ||
        code in 0xFE30..0xFE4F ||
        code in 0xFF00..0xFF60 ||
        code in 0xFFE0..0xFFE6
}

fun truncateString(input: String, width: Int): String {
    require(width >= 0) { "width must not be negative" }
    if (width == 0) return ""
    val builder = StringBuilder()
    var remaining = width
    var index = 0
    while (index < input.length) {
        val codePoint = input.codePointAt(index)
        val charWidth = if (isFullWidthCodePoint(codePoint)) 2 else 1
        if (charWidth > remaining) break
        builder.appendCodePoint(codePoint)
        remaining -= charWidth
        index += Character.charCount(codePoint)
    }
    return builder.toString()
}

fun main() {
    println(truncateString("Hello world", 8))
    println(truncateString("Hello world", 0))
    println(truncateString("abc", 10))
}
```

