import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption

fun atomicWriteTextFile(target: String, content: String): Boolean {
    return atomicWriteTextFile(Path.of(target), content)
}

fun atomicWriteTextFile(target: Path, content: String): Boolean {
    val absolute = target.toAbsolutePath()
    val parent = absolute.parent ?: return false
    if (!Files.isDirectory(parent)) return false
    var temp: Path? = null
    return try {
        val created = Files.createTempFile(parent, "atomic", ".tmp")
        temp = created
        Files.writeString(created, content, StandardCharsets.UTF_8)
        Files.move(created, absolute, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE)
        true
    } catch (error: Exception) {
        temp?.let { pending -> Files.deleteIfExists(pending) }
        false
    }
}

fun main() {
    println(atomicWriteTextFile("build/atomic-demo.txt", "hello"))
    println(atomicWriteTextFile(Path.of("missing", "atomic-demo.txt"), "hello"))
}
