fun findFilesWithSuffix(root: Path, vararg suffixes: String): List<Path> {
    require(suffixes.isNotEmpty()) { "at least one suffix is required" }
    if (!Files.isDirectory(root)) return emptyList()
    val normalized = suffixes.map { suffix -> suffix.lowercase().removePrefix(".") }.toSet()
    return search(root, normalized).sortedBy { path -> path.toString() }
}

private fun search(directory: Path, suffixes: Set<String>): List<Path> {
    val found = ArrayList<Path>()
    Files.walk(directory).use { stream ->
        stream.filter { Files.isRegularFile(it) }.forEach { file ->
            val name = file.fileName.toString().lowercase()
            if (suffixes.any { suffix -> name.endsWith("." + suffix) }) {
                found.add(file)
            }
        }
    }
    return found
}

fun main() {
    println(findFilesWithSuffix(Path.of("."), "kt", "json").size)
}
