private fun convertSingle(identifier: String): String {
    val builder = StringBuilder()
    for (index in identifier.indices) {
        val char = identifier[index]
        if (!char.isUpperCase()) {
            builder.append(char)
            continue
        }
        val previous = if (index > 0) identifier[index - 1] else null
        val next = if (index + 1 < identifier.length) identifier[index + 1] else null
        val startsWord = previous != null && !previous.isUpperCase()
        val endsAcronym = previous != null && previous.isUpperCase() && next != null && next.isLowerCase()
        if (builder.isNotEmpty() && (startsWord || endsAcronym)) {
            builder.append('_')
        }
        builder.append(char.lowercaseChar())
    }
    return builder.toString()
}

