fun splitIdentifier(identifiers: Iterable<String>): List<String> {
    val words = ArrayList<String>()
    for (identifier in identifiers) {
        words.addAll(splitOne(identifier))
    }
    return words
}

private fun splitOne(identifier: String): List<String> {
    val words = ArrayList<String>()
    val current = StringBuilder()
    for (index in identifier.indices) {
        val char = identifier[index]
        if (char == '_' || char == ' ') {
            if (current.isNotEmpty()) {
                words.add(current.toString())
                current.setLength(0)
            }
            continue
        }
        val previous = if (index > 0) identifier[index - 1] else null
        val next = if (index + 1 < identifier.length) identifier[index + 1] else null
        val caseBoundary = current.isNotEmpty() && char.isUpperCase() && previous != null &&
            (!previous.isUpperCase() || (previous.isUpperCase() && next != null && next.isLowerCase()))
        if (caseBoundary) {
            words.add(current.toString())
            current.setLength(0)
        }
        current.append(char)
    }
    if (current.isNotEmpty()) {
        words.add(current.toString())
    }
    return words
}

fun main() {
    println(splitIdentifier(listOf("helloWorld", "hello_world", "HTTPServer", "  ")))
    println(splitIdentifier(emptyList()))
}
```

