import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardOpenOption

fun appendLineToFile(path: Path, record: String): Int {
    val separator = record.indexOf('=')
    require(separator > 0) { "record must have the form key=value" }
    val parent = path.toAbsolutePath().parent
    if (parent != null) {
        Files.createDirectories(parent)
    }
    val line = record.substring(0, separator).trim() + "=" + escapeValue(record.substring(separator + 1))
    Files.writeString(
        path,
        line + System.lineSeparator(),
        StandardCharsets.UTF_8,
        StandardOpenOption.CREATE,
        StandardOpenOption.APPEND
    )
    return Files.readAllLines(path, StandardCharsets.UTF_8).size
}

private fun escapeValue(value: String): String {
    val builder = StringBuilder()
    for (char in value) {
        when (char) {
            '=' -> builder.append("\\=")
            ',' -> builder.append("\\,")
            '"' -> builder.append("\\\"")
            else -> builder.append(char)
        }
    }
    return builder.toString()
}

fun main() {
    val path = Path.of("build", "records.conf")
    println(appendLineToFile(path, "name=John \"Doe\", 123"))
    println(appendLineToFile(path, "city=Berlin"))
}
```

