private val PLACEHOLDER_NAME = Regex("[A-Za-z_][A-Za-z0-9_]*")

fun fillTemplate(template: String, values: Map<String, String>): String {
    require(values.keys.all { key -> PLACEHOLDER_NAME.matches(key) }) { "placeholder names must be valid identifiers" }
    val builder = StringBuilder()
    var index = 0
    while (index < template.length) {
        val char = template[index]
        if (char == '$' && index + 1 < template.length) {
            var end = index + 1
            while (end < template.length && (template[end].isLetterOrDigit() || template[end] == '_')) {
                end++
            }
            val name = template.substring(index + 1, end)
            val replacement = values[name]
            if (name.isNotEmpty() && replacement != null) {
                builder.append(replacement)
                index = end
                continue
            }
        }
        builder.append(char)
        index++
    }
    return builder.toString()
}

fun main() {
    val template = "Hello, \$name! Your age is \$age."
    val values = mapOf("name" to "Alice", "age" to "30")
    println(fillTemplate(template, values))
    println(fillTemplate("Hi \$missing!", values))
}
