fun weightedAverage(values: Iterable<Double>, weights: Iterable<Double>): Double {
    val numbers = values.toList()
    val factors = weights.toList()
    if (numbers.size != factors.size) {
        throw IllegalArgumentException("values and weights must have the same size")
    }
    if (numbers.isEmpty()) return 0.0
    var weightedSum = 0.0
    var weightSum = 0.0
    for (index in numbers.indices) {
        weightedSum += numbers[index] * factors[index]
        weightSum += factors[index]
    }
    return if (weightSum == 0.0) 0.0 else weightedSum / weightSum
}

