fun <T> interleaveVarargs(vararg sequences: Iterable<T>): List<T> {
    return interleave(sequences.map { sequence -> sequence.asSequence() }).toList()
}

private fun <T> interleave(sequences: List<Sequence<T>>): Sequence<T> = sequence {
    val iterators = sequences.map { sequence -> sequence.iterator() }
    while (iterators.any { it.hasNext() }) {
        for (iterator in iterators) {
            if (iterator.hasNext()) {
                yield(iterator.next())
            }
        }
    }
}

fun main() {
    println(interleaveVarargs(listOf(1, 2, 3), listOf(4, 5), listOf(6)))
    println(interleaveVarargs(listOf("a"), listOf("b", "c")))
}
