fun wrapText(text: String, width: Int): List<String> {
    require(width > 0) { "width must be positive" }
    if (text.isEmpty()) return emptyList()
    val lines = ArrayList<String>()
    for (paragraph in text.split('\n')) {
        lines.addAll(wrapParagraph(paragraph, width))
    }
    return lines
}

private fun wrapParagraph(paragraph: String, width: Int): List<String> {
    if (paragraph.isEmpty()) return listOf("")
    val lines = ArrayList<String>()
    var current = StringBuilder()
    for (word in paragraph.split(' ')) {
        if (word.isEmpty()) continue
        if (current.isEmpty()) {
            current.append(word)
        } else if (current.length + 1 + word.length <= width) {
            current.append(' ').append(word)
        } else {
            lines.add(current.toString())
            current = StringBuilder()
            current.append(word)
        }
    }
    if (current.isNotEmpty()) {
        lines.add(current.toString())
    }
    return lines
}

fun main() {
    println(wrapText("This is an example of text wrapping without splitting words.", 30))
    println(wrapText("first paragraph\nsecond paragraph", 20))
}
```

