private fun escapeHtml(line: String): String {
    val builder = StringBuilder()
    for (char in line) {
        when (char) {
            '&' -> builder.append("&amp;")
            '<' -> builder.append("&lt;")
            '>' -> builder.append("&gt;")
            '"' -> builder.append("&quot;")
            '\'' -> builder.append("&#39;")
            else -> builder.append(char)
        }
    }
    return builder.toString()
}

