fun safeRelativePath(root: Path, target: Path): String? {
    val base = root.toAbsolutePath().normalize()
    val resolved = target.toAbsolutePath().normalize()
    if (!resolved.startsWith(base)) return null
    val relative = base.relativize(resolved)
    check(base.resolve(relative).normalize() == resolved) { "the relative path must resolve back to the target" }
    val parts = (0 until relative.nameCount).map { index -> relative.getName(index).toString() }
    return if (parts.isEmpty()) "." else parts.joinToString("/")
}

