class TempFile(private val suffix: String = "") : AutoCloseable {
    private var created: Path? = null

    fun create(): TempFile {
        val directory = Files.createTempDirectory("tempfile-")
        val file = directory.resolve("content" + suffix)
        Files.createFile(file)
        created = file
        return this
    }

    fun path(): Path = requireNotNull(created) { "create must be called before path" }

    override fun close() {
        val file = created ?: return
        Files.deleteIfExists(file)
        file.parent?.let { parent -> Files.deleteIfExists(parent) }
        created = null
    }
}

fun main() {
