```kotlin
@Suppress("UNCHECKED_CAST")
fun <A, R> retry(maxAttempts: Int, delaySeconds: Long, function: (A) -> R): (A) -> R {
    require(maxAttempts > 0) { "maxAttempts must be positive" }
    require(delaySeconds >= 0) { "delaySeconds must not be negative" }
    return { argument ->
        var attempt = 0
        var succeeded = false
        var lastError: Exception? = null
        var result: R? = null
        while (attempt < maxAttempts && !succeeded) {
            try {
                result = function(argument)
                succeeded = true
            } catch (error: Exception) {
                lastError = error
                attempt++
                if (attempt < maxAttempts && delaySeconds > 0) {
                    Thread.sleep(delaySeconds * 1000)
                }
            }
        }
        if (!succeeded) {
            throw requireNotNull(lastError) { "the retried function failed without an exception" }
        }
        result as R
    }
}

fun main() {
    var calls = 0
    val unstable: (Int) -> String = { value ->
        calls++
        if (calls < 3) throw IllegalStateException("temporary failure") else "value " + value
    }
    val retried = retry(3, 0, unstable)
    println(retried(7))
}
```

