```kotlin
fun <A, R> throttle(intervalSeconds: Double, function: (A) -> R): (A) -> R {
    require(intervalSeconds >= 0.0) { "intervalSeconds must not be negative" }
    val intervalMillis = (intervalSeconds * 1000.0).toLong()
    var lastCallTime = 0L
    return { argument ->
        if (intervalMillis > 0) {
            val now = System.currentTimeMillis()
            val elapsed = now - lastCallTime
            if (elapsed < intervalMillis) {
                Thread.sleep(intervalMillis - elapsed)
            }
            lastCallTime = System.currentTimeMillis()
        }
        function(argument)
    }
}

fun main() {
    val throttled = throttle(0.05) { value: String -> value.uppercase() }
    println(throttled("first"))
    println(throttled("second"))
}
```

