    require(bytes.isFinite()) { "bytes must be finite" }
    val size = if (bytes < 0.0) 0.0 else bytes
    val units = listOf("B", "KB", "MB", "GB", "TB")
    var value = size
    var index = 0
    while (value >= 1024.0 && index < units.lastIndex) {
        value /= 1024.0
        index++
    }
    return formatOneDecimal(value) + " " + units[index]
}

private fun formatOneDecimal(value: Double): String = (round(value * 10.0) / 10.0).toString()

fun main() {
    println(formatByteSize(0.0))
    println(formatByteSize(1.0))
    println(formatByteSize(1536.0))
    println(formatByteSize(-1000.0))
    println(formatByteSize(1024.0 * 1024.0 * 1024.0))
}
