```kotlin
fun <T> shiftRight(items: Iterable<T>, shift: Int): List<T> {
    val source = items.toList()
    if (source.isEmpty()) return emptyList()
    val effectiveShift = ((shift % source.size) + source.size) % source.size
    if (effectiveShift == 0) return source.toList()
    val result = ArrayList<T>(source.size)
    for (index in source.indices) {
        result.add(source[(index - effectiveShift + source.size) % source.size])
    }
    return result
}

fun main() {
    println(shiftRight(listOf(1, 2, 3, 4, 5), 2))
    println(shiftRight(listOf(1, 2, 3), 0))
    println(shiftRight(emptyList<Int>(), 3))
    println(shiftRight(listOf(1, 2, 3), -1))
}
