fun renderTable(rows: Iterable<Iterable<String>>): String {
    val table = rows.map { row -> row.toList() }
    if (table.isEmpty()) return ""
    val width = table.maxOf { row -> row.size }
    val widths = IntArray(width)
    for (row in table) {
        for (index in row.indices) {
            widths[index] = maxOf(widths[index], row[index].length)
        }
    }
    val builder = StringBuilder()
    for (row in table) {
        if (builder.isNotEmpty()) builder.append('\n')
        for (index in 0 until width) {
            val cell = if (index < row.size) row[index] else ""
            if (index > 0) builder.append(' ')
            builder.append(cell)
            if (index < width - 1) builder.append(" ".repeat(widths[index] - cell.length))
        }
    }
    return builder.toString()
}

