fun mergeSortedSequences(vararg sequences: Iterable<Double>): List<Double> {
    return mergeAll(sequences.map { sequence -> sequence.toList() })
}

private fun mergeAll(sequences: List<List<Double>>): List<Double> {
    var merged = emptyList<Double>()
    for (sequence in sequences) {
        merged = merge(merged, sequence)
    }
    return merged
}

private fun merge(left: List<Double>, right: List<Double>): List<Double> {
    val result = ArrayList<Double>(left.size + right.size)
    var leftIndex = 0
    var rightIndex = 0
    while (leftIndex < left.size && rightIndex < right.size) {
        if (left[leftIndex] <= right[rightIndex]) {
            result.add(left[leftIndex])
            leftIndex++
        } else {
            result.add(right[rightIndex])
            rightIndex++
        }
    }
    while (leftIndex < left.size) {
        result.add(left[leftIndex])
        leftIndex++
    }
    while (rightIndex < right.size) {
        result.add(right[rightIndex])
        rightIndex++
    }
    return result
}

fun main() {
    println(mergeSortedSequences(listOf(1.0, 4.0, 9.0), listOf(2.0, 3.0), emptyList<Double>()))
}
```

