fun <T> runLengthEncode(items: Iterable<T>): List<Pair<T, Int>> {
    val result = ArrayList<Pair<T, Int>>()
    for (item in items) {
        val last = result.lastOrNull()
        if (last != null && last.first == item) {
            result[result.size - 1] = Pair(last.first, last.second + 1)
        } else {
            result.add(Pair(item, 1))
        }
    }
    return result
}

