```kotlin
fun levenshteinDistance(left: String, right: String): Int {
    val rows = left.length
    val columns = right.length
    val distances = Array(rows + 1) { IntArray(columns + 1) }
    for (row in 0..rows) {
        distances[row][0] = row
    }
    for (column in 0..columns) {
        distances[0][column] = column
    }
    for (row in 1..rows) {
        for (column in 1..columns) {
            val cost = if (left[row - 1] == right[column - 1]) 0 else 1
            distances[row][column] = minOf(
                distances[row - 1][column] + 1,
                distances[row][column - 1] + 1,
                distances[row - 1][column - 1] + cost
            )
        }
    }
    return distances[rows][columns]
}

fun main() {
    println(levenshteinDistance("kitten", "sitting"))
    println(levenshteinDistance("", ""))
}
```

