}

private fun windowSums(data: List<Double>, windowSize: Int): List<Double> {
    require(windowSize in 1..data.size) { "windowSize is out of range" }
    val result = ArrayList<Double>(data.size - windowSize + 1)
    var windowTotal = 0.0
    for (index in data.indices) {
        windowTotal += data[index]
        if (index >= windowSize) {
            windowTotal -= data[index - windowSize]
        }
        if (index >= windowSize - 1) {
            result.add(windowTotal)
        }
    }
    return result
}

fun main() {
    println(fixedWindowSum(listOf(1.0, 2.0, 3.0, 4.0), 2))
    println(fixedWindowSum(listOf(1.0, 2.0), 5))
}
