private val DEFAULT_BRACKETS: Map<Char, Char> = mapOf('(' to ')', '[' to ']', '{' to '}')

fun checkBrackets(characters: Iterable<Char>, brackets: Map<Char, Char> = DEFAULT_BRACKETS): Boolean {
    val stack = ArrayDeque<Char>()
    val closers = brackets.values.toSet()
    for (char in characters) {
        when {
            brackets.containsKey(char) -> stack.addLast(char)
            char in closers -> {
                val open = stack.removeLastOrNull() ?: return false
                if (brackets[open] != char) return false
            }
            else -> Unit
        }
    }
    return stack.isEmpty()
}

