private val DEFAULT_UNITS: Map<String, Int> = mapOf("h" to 3600, "m" to 60, "s" to 1)

fun parseDuration(text: String, units: Map<String, Int> = DEFAULT_UNITS): Int {
    var total = 0
    var index = 0
    while (index < text.length) {
        val amountStart = index
        while (index < text.length && text[index].isDigit()) {
            index++
        }
        if (index == amountStart) return 0
        val amount = text.substring(amountStart, index).toIntOrNull() ?: return 0
        val unitStart = index
        while (index < text.length && text[index].isLetter()) {
            index++
        }
        if (unitStart == index) return 0
        val unit = text.substring(unitStart, index).lowercase()
        val multiplier = units[unit] ?: return 0
        total += amount * multiplier
    }
    return total
}

