fun <T> transpose(matrix: Iterable<Iterable<T>>): List<List<T>> {
    val rows = matrix.map { row -> row.toList() }
    if (rows.isEmpty()) return emptyList()
    val width = rows.minOf { row -> row.size }
    if (width == 0) return emptyList()
    return (0 until width).map { column -> rows.map { row -> row[column] } }
