fun parseQueryString(
    query: String,
    defaultValues: Map<String, List<String>> = emptyMap()
): Map<String, List<String>> {
    require(defaultValues.values.all { values -> values.isNotEmpty() }) { "default values must not be empty" }
    val body = query.trim().removePrefix("?")
    if (body.isEmpty()) {
        return defaultValues.mapValues { entry -> entry.value.toList() }
    }
    val collected = linkedMapOf<String, MutableList<String>>()
    for (pair in body.split("&")) {
        val index = pair.indexOf('=')
        if (index <= 0) continue
        val key = pair.substring(0, index)
        val value = pair.substring(index + 1)
        collected.getOrPut(key) { mutableListOf() }.add(value)
    }
    for ((key, values) in defaultValues) {
        if (key !in collected) {
            collected[key] = values.toMutableList()
        }
    }
    return collected.mapValues { entry -> entry.value.toList() }
}

fun main() {
