        if (trimmed.isEmpty()) {
            result.add("")
            continue
        }
        if (trimmed.startsWith("}")) {
            depth = (depth - 1).coerceAtLeast(0)
        }
        result.add(" ".repeat(depth * indentStep) + trimmed)
        if (trimmed.endsWith("{")) {
            depth++
        }
    }
    return result
}

