import java.security.MessageDigest

fun computeCacheKey(map: Map<String, Any?>): String {
    val sortedMap = map.toSortedMap()
    val payload = sortedMap.entries.joinToString(",") { entry ->
        "${entry.key}=${entry.value.toString()}"
    }
