class Pluralizer(private val irregularWords: Map<String, String> = IRREGULAR_PLURALS) {
    fun pluralize(word: String, count: Int): String {
        if (count == 1) {
            return word
        }
        val lower = word.lowercase()
        irregularWords[lower]?.let { irregular -> return irregular }
        return when {
