fun longestCommonPrefix(strings: Iterable<String>): String {
    val values = strings.toList()
    if (values.isEmpty() || values.any { value -> value.isEmpty() }) {
        return ""
    }
    var prefix = values.first()
    for (value in values.drop(1)) {
        var limit = 0
        while (limit < prefix.length && limit < value.length && prefix[limit] == value[limit]) {
            limit++
        }
        prefix = prefix.substring(0, limit)
    }
    return prefix
}

