import kotlin.random.Random

fun <T> reservoirSampling(iterable: Iterable<T>, k: Int, seed: Long): List<T> {
    if (k <= 0) {
        return emptyList()
    }
    val random = Random(seed)
    val reservoir = mutableListOf<T>()
    var index = 0
    for (item in iterable) {
        if (index < k) {
            reservoir.add(item)
        } else {
            val slot = random.nextInt(index + 1)
            if (slot < k) {
                reservoir[slot] = item
            }
        }
        index++
    }
    check(reservoir.size <= k) { "reservoir must not exceed k elements" }
    return reservoir
}

fun main() {
    val data = listOf("A", "B", "C", "D", "E", "F", "G", "H")
    println(reservoirSampling(data, 3, 42L))
    println(reservoirSampling(data, 3, 42L))
}
